	fmt.Println(unique, sorted)

	fmt.Println(slices.Equal(nums, []int{5, 2, 8, 2, 9}))

	// Output:
	// true 1
	// 2 9
	// [2 2 5 8 9]
	// 3 true
	// [2 5 8 9] [2 5 8 9 0]
