	err = json.Unmarshal([]byte(`{"name":"pen","color":"blue"}`), &it, json.RejectUnknownMembers(true))
	fmt.Println(errors.Is(err, json.ErrUnknownName))

	// Output:
	// {"name":"pen","tags":[]} <nil>
