		// wait until every goroutine in the bubble is blocked again, so
		// the sweep has definitely finished before we look.
		time.Sleep(10 * time.Second)
		synctest.Wait()
		if n := c.Len(); n != 0 {
			t.Fatalf("sweeper left %d entries", n)
		}
	})
