// Sum adds 1..n recursively. Go has no tail-call optimization, so this
// uses one stack frame per call: a million calls need tens of
// megabytes of stack, which the runtime grows on demand.
func Sum(n int) int {
	if n == 0 {
		return 0
	}
	return n + Sum(n-1)
}

