examples/m02/controlflow/controlflow_tes.content:
package controlflow

import (
	"fmt"
	"strconv"
)

// [start if]

func Example_ifWithInit() {
	// The init statement's variables exist only inside the if/else.
	if n, err := strconv.Atoi("42"); err != nil {
		fmt.Println("not a number:", err)
	} else if n > 40 {
		fmt.Println("big:", n)
	} else {
		fmt.Println("small:", n)
	}

	// Output:
	// big: 42
}

// [end if]

// [start for]

func Example_forLoops() {
	// 1. Classic three-part loop.
	for i := 0; i < 3; i++ {
		fmt.Println("classic", i)
	}

	// 2. Condition only: Go's "while".
	n := 1
	for n < 100 {
		n *= 3
	}
	fmt.Println(n)

	// 3. Range over an integer (Go 1.22+): i goes 0, 1.
	for i := range 2 {
		fmt.Println("range int", i)
	}

	// 4. Range over a slice gives index and value.
	for i, name := range []string{"ana", "bo"} {
		fmt.Println(i, name)
	}

	// 5. Infinite loop with break.
	tries := 0
	for {
		tries++
		if tries == 3 {
			break
		}
	}
	fmt.Println("tries:", tries)

	// Output:
	// classic 0
	// classic 1
	// classic 2
	// 243
	// range int 0
	// range int 1
	// 0 ana
	// 1 bo
	// tries: 3
}

// [end for]

// [start switch]

func describe(code int) string {
	switch code {
	case 200, 201, 204: // several values in one case
		return "success"
	case 301, 302:
		return "redirect"
	case 404:
		return "not found"
	default:
		return "other"
	}
	// No break needed: Go never falls through unless you say so.
}

func grade(score int) string {
	switch { // no expression: same as "switch true"
	case score >= 90:
		return "A"
	case score >= 75:
		return "B"
	default:
		return "C"
	}
}

func Example_switch() {
	fmt.Println(describe(204), describe(302), describe(500))
	fmt.Println(grade(95), grade(80), grade(10))

	// Output:
	// success redirect other
	// A B C
}

// [end switch]

// [start fallthrough]

func Example_fallthrough() {
	switch n := 1; n {
	case 1:
		fmt.Println("one")
		fallthrough // run the next case body, without checking it
	case 2:
		fmt.Println("two")
	case 3:
		fmt.Println("three")
	}

	// Output:
	// one
	// two
}

// [end fallthrough]

// [start labels]

func Example_labels() {
	grid := [][]int{
		{1, 2, 3},
		{4, -1, 6},
		{7, 8, 9},
	}

search:
	for r, row := range grid {
		for c, v := range row {
			if v < 0 {
				fmt.Printf("negative at row %d, col %d\n", r, c)
				break search // leaves BOTH loops
			}
		}
	}

	// Output:
	// negative at row 1, col 1
}

// [end labels]

// [start breakswitch]

func Example_breakInsideSwitch() {
	// break inside a switch only leaves the switch, not the loop.
	for i := range 5 {
		switch i {
		case 2:
			break // ends the switch; the loop keeps going
		}
		fmt.Println("unlabeled", i)
		if i == 2 {
			break // this one is outside the switch: it ends the loop
		}
	}

loop:
	for i := range 5 {
		switch i {
		case 1:
			break loop // a label makes break leave the loop
		}
		fmt.Println("labeled", i)
	}

	// Output:
	// unlabeled 0
	// unlabeled 1
	// unlabeled 2
	// labeled 0
}

// [end breakswitch]

examples/m02/deferring/deferring_test.go.content:
package deferring

import (
	"errors"
	"fmt"
	"os"
	"path/filepath"
)

// [start order]

func Example_order() {
	fmt.Println("start")
	defer fmt.Println("deferred 1")
	defer fmt.Println("deferred 2") // runs first: last in, first out
	fmt.Println("end")

	// Output:
	// start
	// end
	// deferred 2
	// deferred 1
}

// [end order]

// [start args]

func Example_argumentsEvaluatedEarly() {
	x := 1
	defer fmt.Println("deferred sees x =", x) // x is evaluated NOW
	x = 2
	fmt.Println("x is now", x)

	// Output:
	// x is now 2
	// deferred sees x = 1
}

// [end args]

// [start closure]

func Example_closureSeesLatest() {
	x := 1
	defer func() { fmt.Println("closure sees x =", x) }() // reads x later
	x = 2

	// Output:
	// closure sees x = 2
}

// [end closure]

// [start cleanup]

// firstLine shows the standard pattern: acquire, check the error,
// then defer the release right away.
func firstLine(path string) (string, error) {
	f, err := os.Open(path)
	if err != nil {
		return "", err
	}
	defer f.Close() // runs on every return path below

	buf := make([]byte, 64)
	n, err := f.Read(buf)
	if err != nil {
		return "", err
	}
	for i, b := range buf[:n] {
		if b == '\n' {
			return string(buf[:i]), nil
		}
	}
	return string(buf[:n]), nil
}

func Example_cleanup() {
	dir, _ := os.MkdirTemp("", "defer-example")
	defer os.RemoveAll(dir)

	path := filepath.Join(dir, "notes.txt")
	_ = os.WriteFile(path, []byte("hello\nworld\n"), 0o644)

	line, err := firstLine(path)
	fmt.Println(line, err)

	_, err = firstLine(filepath.Join(dir, "missing.txt"))
	fmt.Println(errors.Is(err, os.ErrNotExist))

	// Output:
	// hello <nil>
	// true
}

// [end cleanup]

// [start named]

// safeDivide turns a panic into an error by changing the named
// result from a deferred function. Panics are covered in Module 5.
func safeDivide(a, b int) (result int, err error) {
	defer func() {
		if r := recover(); r != nil {
			err = fmt.Errorf("recovered: %v", r)
		}
	}()
	return a / b, nil
}

func Example_modifyNamedResult() {
	fmt.Println(safeDivide(10, 2))
	fmt.Println(safeDivide(1, 0))

	// Output:
	// 5 <nil>
	// 0 recovered: runtime error: integer divide by zero
}

// [end named]

examples/m02/functions/functions_test.go.content:
package functions

import (
	"errors"
	"fmt"
	"strings"
)

// [start multi]

// divide returns the quotient, or an error when b is zero.
func divide(a, b float64) (float64, error) {
	if b == 0 {
		return 0, errors.New("division by zero")
	}
	return a / b, nil
}

func Example_multipleReturns() {
	if q, err := divide(10, 4); err == nil {
		fmt.Println(q)
	}
	_, err := divide(1, 0)
	fmt.Println(err)

	// Output:
	// 2.5
	// division by zero
}

// [end multi]

// [start named]

// split uses named results. They start at their zero values,
// and a bare "return" returns their current values.
func split(full string) (first, last string) {
	first, last, _ = strings.Cut(full, " ")
	return
}

func Example_namedResults() {
	f, l := split("Rob Pike")
	fmt.Println(l + ", " + f)

	// Output:
	// Pike, Rob
}

// [end named]

// [start variadic]

func sum(nums ...int) int { // nums is a []int inside the function
	total := 0
	for _, n := range nums {
		total += n
	}
	return total
}

func Example_variadic() {
	fmt.Println(sum())
	fmt.Println(sum(1, 2, 3))

	values := []int{10, 20, 30}
	fmt.Println(sum(values...)) // spread an existing slice

	// Output:
	// 0
	// 6
	// 60
}

// [end variadic]

// [start values]

func apply(nums []int, f func(int) int) []int {
	out := make([]int, 0, len(nums))
	for _, n := range nums {
		out = append(out, f(n))
	}
	return out
}

func Example_functionValues() {
	double := func(n int) int { return n * 2 }

	fmt.Println(apply([]int{1, 2, 3}, double))
	fmt.Println(apply([]int{1, 2, 3}, func(n int) int { return n * n }))

	// Output:
	// [2 4 6]
	// [1 4 9]
}

// [end values]

// [start closures]

// counter returns a function that remembers count between calls.
func counter() func() int {
	count := 0
	return func() int {
		count++ // captures the variable, not a copy of its value
		return count
	}
}

func Example_closures() {
	next := counter()
	fmt.Println(next(), next(), next())

	other := counter() // each call creates a new, independent count
	fmt.Println(other())

	// Output:
	// 1 2 3
	// 1
}

// [end closures]

// [start loopvar]

func Example_loopVariables() {
	var funcs []func() int
	for i := range 3 {
		// Since Go 1.22 every iteration has its own i, so each
		// closure captures a different variable.
		funcs = append(funcs, func() int { return i })
	}
	for _, f := range funcs {
		fmt.Println(f())
	}

	// Output:
	// 0
	// 1
	// 2
}

// [end loopvar]

examples/m02/numbers/numbers_test.go.content:
package numbers

import (
	"fmt"
	"math"
	"strconv"
)

// [start conversion]

func Example_conversion() {
	var i int = 42
	var f float64 = float64(i) // conversions are always explicit
	var u uint8 = uint8(i)

	// Converting a float to an int truncates toward zero.
	// (int(3.99) on a constant would not even compile: the
	// compiler refuses constant conversions that lose information.)
	pos, neg := 3.99, -3.99
	fmt.Println(int(pos), int(neg))
	fmt.Println(f, u)

	// Integer division truncates too. Convert first for a float result.
	fmt.Println(7/2, float64(7)/2)

	// Output:
	// 3 -3
	// 42 42
	// 3 3.5
}

// [end conversion]

// [start overflow]

func Example_overflow() {
	var small int8 = 127
	small++ // wraps around silently at run time
	fmt.Println(small)

	var count uint = 0
	count-- // unsigned underflow wraps to the maximum value
	fmt.Println(count == math.MaxUint)

	// A conversion that does not fit keeps only the low bits.
	big := 300
	fmt.Println(uint8(big))

	// Output:
	// -128
	// true
	// 44
}

// [end overflow]

// [start floats]

func Example_floats() {
	a, b := 0.1, 0.2
	fmt.Println(a+b == 0.3)
	fmt.Println(a + b)

	// Compare floats with a tolerance instead.
	fmt.Println(math.Abs((a+b)-0.3) < 1e-9)

	// Output:
	// false
	// 0.30000000000000004
	// true
}

// [end floats]

// [start strconv]

func Example_strconv() {
	n, err := strconv.Atoi("123")
	fmt.Println(n+1, err)

	_, err = strconv.Atoi("12a")
	fmt.Println(err)

	// string(65) is NOT "65": it converts a number to a character.
	fmt.Println(strconv.Itoa(65), string(rune(65)))

	// Output:
	// 124 <nil>
	// strconv.Atoi: parsing "12a": invalid syntax
	// 65 A
}

// [end strconv]

examples/m02/pointers/pointers_test.go.content:
package pointers

import "fmt"

// [start basics]

func Example_basics() {
	x := 10
	p := &x // p has type *int and holds the address of x

	fmt.Println(*p) // dereference: read the value p points to
	*p = 20         // write through the pointer
	fmt.Println(x)

	var nothing *int // the zero value of a pointer is nil
	fmt.Println(nothing == nil)

	// Output:
	// 10
	// 20
	// true
}

// [end basics]

// [start passing]

// Go always passes arguments by value: the function gets a copy.
func resetValue(n int) { n = 0 }

// Passing a pointer copies the address, so the function can
// change the caller's variable.
func resetPointer(n *int) { *n = 0 }

func Example_passByValue() {
	a, b := 5, 5
	resetValue(a)
	resetPointer(&b)
	fmt.Println(a, b)

	// Output:
	// 5 0
}

// [end passing]

// [start structs]

type Player struct {
	Name  string
	Score int
}

func addPoints(p *Player, points int) {
	p.Score += points // same as (*p).Score: Go dereferences for you
}

func Example_structPointers() {
	ana := Player{Name: "Ana"}
	addPoints(&ana, 10)
	addPoints(&ana, 5)
	fmt.Println(ana.Name, ana.Score)

	// Output:
	// Ana 15
}

// [end structs]

// [start escape]

// newPlayer returns a pointer to a local variable. This is safe in
// Go: the compiler notices the variable outlives the function and
// allocates it on the heap ("escape analysis").
func newPlayer(name string) *Player {
	p := Player{Name: name}
	return &p
}

func Example_returnPointer() {
	bo := newPlayer("Bo")
	bo.Score = 7
	fmt.Println(bo.Name, bo.Score)

	n := new(int) // new(T) allocates a zero T and returns *T
	*n = 3
	fmt.Println(*n)

	// Output:
	// Bo 7
	// 3
}

// [end escape]

// [start nil]

func scoreOf(p *Player) int {
	if p == nil { // guard before dereferencing
		return 0
	}
	return p.Score
}

func Example_nilPointer() {
	var missing *Player
	fmt.Println(scoreOf(missing))

	defer func() { fmt.Println("recovered:", recover()) }()
	fmt.Println(missing.Score) // dereferencing nil panics

	// Output:
	// 0
	// recovered: runtime error: invalid memory address or nil pointer dereference
}

// [end nil]

examples/m02/scope/scope_test.go.content:
package scope

import (
	"errors"
	"fmt"
)

func load(name string) (string, error) {
	if name == "" {
		return "", errors.New("empty name")
	}
	return "data for " + name, nil
}

// [start blocks]

func Example_blocks() {
	x := "outer"
	{
		x := "inner" // a NEW variable that shadows the outer x
		fmt.Println(x)
	}
	fmt.Println(x)

	if y := len(x); y > 3 {
		fmt.Println("y exists only in this if:", y)
	}
	// fmt.Println(y) would not compile here

	// Output:
	// inner
	// outer
	// y exists only in this if: 5
}

// [end blocks]

// [start errshadow]

// buggy intends to report the error from load, but := inside the if
// block declares a brand new err that disappears at the closing brace.
func buggy(name string) error {
	var err error
	if name != "skip" {
		data, err := load(name) // shadows the outer err
		_ = data
		_ = err
	}
	return err // always nil
}

// fixed assigns to the existing variable with = instead.
func fixed(name string) error {
	var err error
	if name != "skip" {
		_, err = load(name)
	}
	return err
}

func Example_shadowedError() {
	fmt.Println(buggy(""))
	fmt.Println(fixed(""))

	// Output:
	// <nil>
	// empty name
}

// [end errshadow]

// [start universe]

func Example_shadowBuiltins() {
	// Built-in names like len, true or string are not keywords.
	// They live in the "universe" scope and CAN be shadowed.
	len := 3 // now len is an int in this function
	fmt.Println(len)
	// len("abc") would fail to compile here: len is not a function

	// Output:
	// 3
}

// [end universe]

