	g, _ := WithContext(context.Background())
	g.SetLimit(3)

	var running, peak atomic.Int32
	for range 12 {
		g.Go(func() error {
			now := running.Add(1)
			for {
				p := peak.Load()
				if now <= p || peak.CompareAndSwap(p, now) {
					break
				}
			}
			time.Sleep(2 * time.Millisecond)
			running.Add(-1)
			return nil
		})
	}

	fmt.Println(g.Wait(), peak.Load() <= 3)

	// Output:
	// <nil> true
}

