package shutdown

import (
	"context"
	"errors"
	"fmt"
	"net"
	"net/http"
	"sync"
	"time"
)

// [start server]

// serve runs an HTTP server until ctx is cancelled (in a real program,
// by SIGINT or SIGTERM via signal.NotifyContext), then shuts down
// gracefully: stop accepting, let in-flight requests finish, give up
// after a deadline.
func serve(ctx context.Context, ln net.Listener, handler http.Handler) error {
	srv := &http.Server{Handler: handler, ReadHeaderTimeout: 5 * time.Second}

	errCh := make(chan error, 1)
	go func() { errCh <- srv.Serve(ln) }()

	select {
	case err := <-errCh: // the server failed on its own
		return err
	case <-ctx.Done(): // asked to stop
	}

	shutdownCtx, cancel := context.WithTimeout(context.Background(), 5*time.Second)
	defer cancel()
	if err := srv.Shutdown(shutdownCtx); err != nil {
		return fmt.Errorf("shutdown: %w", err)
	}
	if err := <-errCh; !errors.Is(err, http.ErrServerClosed) {
		return err
	}
	return nil
}

// [end server]

// [start demo]

func Example_gracefulShutdown() {
	ln, _ := net.Listen("tcp", "127.0.0.1:0")
	ctx, stop := context.WithCancel(context.Background())

	started := make(chan struct{})
	handler := http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		close(started)
		time.Sleep(50 * time.Millisecond) // a slow, in-flight request
		fmt.Fprint(w, "finished")
	})

	done := make(chan error, 1)
	go func() { done <- serve(ctx, ln, handler) }()

	var wg sync.WaitGroup
	wg.Add(1)
	var body string
	go func() {
		defer wg.Done()
		resp, err := http.Get("http://" + ln.Addr().String())
		if err != nil {
			body = err.Error()
			return
		}
		defer resp.Body.Close()
		b := make([]byte, 64)
		n, _ := resp.Body.Read(b)
		body = string(b[:n])
	}()

	<-started
	stop() // shutdown begins while the request is still running

	wg.Wait()
	fmt.Println("in-flight request:", body)
	fmt.Println("serve returned:", <-done)

	// Output:
	// in-flight request: finished
	// serve returned: <nil>
}

// [end demo]

examples/m07/workerpool/workerpool_test..content:
package workerpool

import (
	"context"
	"fmt"
	"strings"
	"sync"
)

// [start pool]

type job struct {
	id   int
	text string
}

type result struct {
	id    int
	words int
}

// countWords runs a fixed number of workers over a stream of jobs.
func countWords(ctx context.Context, texts []string, workers int) []int {
	jobs := make(chan job)
	results := make(chan result)

	// 1. Start the workers. Each reads jobs until the channel closes.
	var wg sync.WaitGroup
	for range workers {
		wg.Add(1)
		go func() {
			defer wg.Done()
			for j := range jobs {
				r := result{id: j.id, words: len(strings.Fields(j.text))}
				select {
				case results <- r:
				case <-ctx.Done():
					return
				}
			}
		}()
	}

	// 2. Feed the jobs, then close the channel so workers stop.
	go func() {
		defer close(jobs)
		for i, t := range texts {
			select {
			case jobs <- job{id: i, text: t}:
			case <-ctx.Done():
				return
			}
		}
	}()

	// 3. Close results once every worker is done.
	go func() {
		wg.Wait()
		close(results)
	}()

	// 4. Collect. Results arrive in any order, so place them by id.
	counts := make([]int, len(texts))
	for r := range results {
		counts[r.id] = r.words
	}
	return counts
}

func Example_workerPool() {
	texts := []string{
		"go is fun",
		"channels connect goroutines",
		"",
		"a worker pool bounds concurrency to a fixed size",
	}
	fmt.Println(countWords(context.Background(), texts, 2))

	// Output:
	// [3 3 0 9]
}

// [end pool]

