// Package loganalyzer is the running example for Module 10: the same
// analysis written naively and then optimized step by step, guided by
// benchmarks and profiles.
package loganalyzer

// Stats summarizes access log lines of the form
//
//	2026-10-16T09:30:00Z GET /api/users 200 12ms
type Stats struct {
	Requests  int
	ByStatus  map[int]int
	ByPath    map[string]int
	TotalMs   int
	Malformed int
}

examples/m10/loganalyzer/better.go.content:
package loganalyzer

import (
	"regexp"
	"strconv"
	"strings"
)

// [start better]

// lineRE is compiled once, when the package is initialized.
var lineRE = regexp.MustCompile(`^(\S+) (\S+) (\S+) (\d{3}) (\d+)ms$`)

// AnalyzeBetter applies the first fix the profile points at: compile
// the regular expression once. Everything else is unchanged.
func AnalyzeBetter(lines []string) Stats {
	s := Stats{ByStatus: map[int]int{}, ByPath: map[string]int{}}
	for _, line := range lines {
		m := lineRE.FindStringSubmatch(line)
		if m == nil {
			s.Malformed++
			continue
		}
		status, _ := strconv.Atoi(m[4])
		ms, _ := strconv.Atoi(m[5])
		s.Requests++
		s.ByStatus[status]++
		s.ByPath[strings.ToLower(m[3])]++
		s.TotalMs += ms
	}
	return s
}

// [end better]

examples/m10/loganalyzer/fast.go.content:
package loganalyzer

import (
	"strconv"
	"strings"
)

// [start fast]

// AnalyzeFast replaces the regular expression with direct string
// scanning, avoids allocating keys that are already lowercase, and
// sizes the maps up front.
func AnalyzeFast(lines []string) Stats {
	s := Stats{ByStatus: make(map[int]int, 8), ByPath: make(map[string]int, 64)}
	for _, line := range lines {
		path, status, ms, ok := parseLine(line)
		if !ok {
			s.Malformed++
			continue
		}
		s.Requests++
		s.ByStatus[status]++
		s.ByPath[lowerIfNeeded(path)]++
		s.TotalMs += ms
	}
	return s
}

// parseLine splits "time method path status NNms" without allocating.
func parseLine(line string) (path string, status, ms int, ok bool) {
	_, rest, ok1 := strings.Cut(line, " ") // time
	_, rest, ok2 := strings.Cut(rest, " ") // method
	path, rest, ok3 := strings.Cut(rest, " ")
	code, dur, ok4 := strings.Cut(rest, " ")
	if !(ok1 && ok2 && ok3 && ok4) || len(code) != 3 || !strings.HasSuffix(dur, "ms") || strings.Contains(dur, " ") {
		return "", 0, 0, false
	}
	status, err1 := strconv.Atoi(code)
	ms, err2 := strconv.Atoi(dur[:len(dur)-2])
	if err1 != nil || err2 != nil || ms < 0 || path == "" {
		return "", 0, 0, false
	}
	return path, status, ms, true
}

// lowerIfNeeded returns s unchanged (no allocation) when it has no
// uppercase ASCII letters, which is the common case for URL paths.
func lowerIfNeeded(s string) string {
	for i := 0; i < len(s); i++ {
		if c := s[i]; 'A' <= c && c <= 'Z' || c >= 0x80 {
			return strings.ToLower(s)
		}
	}
	return s
}

// [end fast]

examples/m10/loganalyzer/naive.go.content:
package loganalyzer

import (
	"fmt"
	"regexp"
	"strconv"
	"strings"
)

// [start naive]

// AnalyzeNaive is written the way code often starts: clear, but with
// no thought for cost.
func AnalyzeNaive(lines []string) Stats {
	s := Stats{ByStatus: map[int]int{}, ByPath: map[string]int{}}
	for _, line := range lines {
		// Compiling a regular expression on every line is expensive.
		re := regexp.MustCompile(`^(\S+) (\S+) (\S+) (\d{3}) (\d+)ms$`)
		m := re.FindStringSubmatch(line)
		if m == nil {
			s.Malformed++
			continue
		}
		status, _ := strconv.Atoi(m[4])
		ms, _ := strconv.Atoi(m[5])

		// Building a key with Sprintf allocates a new string per line.
		key := fmt.Sprintf("%s", strings.ToLower(m[3]))

		s.Requests++
		s.ByStatus[status]++
		s.ByPath[key]++
		s.TotalMs += ms
	}
	return s
}

// [end naive]

