		"BASE_URL":         "https://sho.rt",
		"LOG_LEVEL":        "debug",
		"SHUTDOWN_TIMEOUT": "30s",
	}))
	fmt.Println(err)
	fmt.Println(cfg.Addr, cfg.BaseURL, cfg.LogLevel, cfg.ShutdownTimeout, cfg.RateLimit)

	_, err = Load(env(map[string]string{
		"LOG_LEVEL":        "loud",
		"SHUTDOWN_TIMEOUT": "soon",
		"RATE_LIMIT":       "-1",
	}))
	fmt.Println(err)
	// Output:
