	_, err := Load(env(map[string]string{"BASE_URL": "https://sho.rt", "DATABASE_URL": "x", "DATABASE_URL_FILE": "/y"}))
	if err == nil || !strings.Contains(err.Error(), "not both") {
		t.Fatalf("err = %v", err)
	}
}

