// Code generated by "go run ../enumgen -type=Color"; DO NOT EDIT.

package color

import "fmt"

// String returns the text form of v.
func (v Color) String() string {
	switch v {
	case ColorRed:
		return "red"
	case ColorAmber:
		return "amber"
	case ColorGreen:
		return "green"
	}
	return fmt.Sprintf("Color(%d)", int(v))
}

// ParseColor returns the Color whose text form is s.
func ParseColor(s string) (Color, error) {
	switch s {
	case "red":
		return ColorRed, nil
	case "amber":
		return ColorAmber, nil
	case "green":
		return ColorGreen, nil
	}
	return 0, fmt.Errorf("invalid Color %q", s)
}

// ColorValues returns every defined Color, in order.
func ColorValues() []Color {
	return []Color{ColorRed, ColorAmber, ColorGreen}
}

// MarshalText implements encoding.TextMarshaler, so JSON, flags and
// slog use the text form.
func (v Color) MarshalText() ([]byte, error) { return []byte(v.String()), nil }

// UnmarshalText implements encoding.TextUnmarshaler.
func (v *Color) UnmarshalText(b []byte) error {
	p, err := ParseColor(string(b))
	if err != nil {
		return err
	}
	*v = p
	return nil
}

