package rediscache

import (
	"context"
	"fmt"
	"log/slog"
	"os"
	"sync"
	"sync/atomic"
	"testing"
	"time"

	"github.com/redis/go-redis/v9"
)

func client(t *testing.T) *redis.Client {
	t.Helper()
	addr := os.Getenv("TEST_REDIS_ADDR")
	if addr == "" {
		t.Skip("TEST_REDIS_ADDR not set; see examples/thirdparty/README.md")
	}
	rdb := redis.NewClient(&redis.Options{Addr: addr})
	t.Cleanup(func() { rdb.Close() })
	return rdb
}

// slowSource simulates a database: 50 ms per load, and counts loads.
type slowSource struct{ loads atomic.Int64 }

func (s *slowSource) Load(ctx context.Context, key string) (string, error) {
	s.loads.Add(1)
	time.Sleep(50 * time.Millisecond)
	return "value of " + key, nil
}

func prefix(t *testing.T) string { return fmt.Sprintf("test:%s:%d:", t.Name(), time.Now().UnixNano()) }

func TestCacheAside(t *testing.T) {
	src := &slowSource{}
	c := New(client(t), prefix(t), 200*time.Millisecond, src.Load, slog.New(slog.DiscardHandler))
	ctx := t.Context()

	for i, want := range []int64{1, 1, 1} { // first call loads, the next two hit
		start := time.Now()
		v, err := c.Get(ctx, "user:42")
		if err != nil || v != "value of user:42" {
			t.Fatal(v, err)
		}
		t.Logf("call %d: %v, loads so far %d", i+1, time.Since(start).Round(100*time.Microsecond), src.loads.Load())
		if src.loads.Load() != want {
			t.Fatalf("loads = %d, want %d", src.loads.Load(), want)
		}
	}

	time.Sleep(300 * time.Millisecond) // past the TTL
	c.Get(ctx, "user:42")
	if src.loads.Load() != 2 {
		t.Fatalf("after TTL: loads = %d, want 2", src.loads.Load())
	}

	c.Invalidate(ctx, "user:42")
	c.Get(ctx, "user:42")
	if src.loads.Load() != 3 {
		t.Fatalf("after Invalidate: loads = %d, want 3", src.loads.Load())
	}
}

// [start stampede]

func TestStampede(t *testing.T) {
	rdb := client(t)
	for _, coalesce := range []bool{false, true} {
		src := &slowSource{}
		c := New(rdb, prefix(t), time.Minute, src.Load, slog.New(slog.DiscardHandler))
		c.Coalesce = coalesce

		var wg sync.WaitGroup
		for range 100 { // 100 requests for the same cold key at once
			wg.Go(func() {
				if _, err := c.Get(t.Context(), "popular"); err != nil {
					t.Error(err)
				}
			})
		}
		wg.Wait()
		t.Logf("coalesce=%-5v 100 concurrent misses caused %d loads", coalesce, src.loads.Load())
		if coalesce && src.loads.Load() != 1 {
			t.Fatalf("with coalescing, want exactly 1 load, got %d", src.loads.Load())
		}
	}
}

// [end stampede]

// [start down]

func TestRedisDown(t *testing.T) {
	// Nothing listens on this port: every Redis call fails quickly.
	rdb := redis.NewClient(&redis.Options{Addr: "127.0.0.1:1", DialTimeout: 100 * time.Millisecond, MaxRetries: -1})
	defer rdb.Close()
	src := &slowSource{}
	c := New(rdb, "x:", time.Minute, src.Load, slog.New(slog.DiscardHandler))

	v, err := c.Get(t.Context(), "k")
	if err != nil || v != "value of k" {
		t.Fatalf("Get with Redis down = %q, %v; want the loaded value", v, err)
	}
}

// [end down]

// Package rediscache holds the caching examples for lesson 13.5: a
// cache-aside layer over Redis, with request coalescing.
package rediscache

import (
	"context"
	"errors"
	"log/slog"
	"time"

	"github.com/redis/go-redis/v9"
	"golang.org/x/sync/singleflight"
)

// [start cache]

// A Loader fetches a value from the source of truth, such as a database.
type Loader func(ctx context.Context, key string) (string, error)

// Cache implements cache-aside: look in Redis first, and on a miss,
// load from the source and store the result with a TTL.
type Cache struct {
	rdb    *redis.Client
	load   Loader
	ttl    time.Duration
	prefix string
	logger *slog.Logger

	Coalesce bool // share one load among concurrent misses for a key
	group    singleflight.Group
}

func New(rdb *redis.Client, prefix string, ttl time.Duration, load Loader, logger *slog.Logger) *Cache {
	return &Cache{rdb: rdb, load: load, ttl: ttl, prefix: prefix, logger: logger, Coalesce: true}
}

// Get returns the value for key. If Redis is unavailable, it falls back
// to the loader: a cache must make things faster, never less available.
func (c *Cache) Get(ctx context.Context, key string) (string, error) {
	v, err := c.rdb.Get(ctx, c.prefix+key).Result()
	switch {
	case err == nil:
		return v, nil // hit
	case errors.Is(err, redis.Nil):
		// miss: fall through
	default:
		c.logger.Warn("cache read failed", "key", key, "error", err)
	}

	if !c.Coalesce {
		return c.loadAndStore(ctx, key)
	}
	// Concurrent misses for the same key wait for one load (the
	// "thundering herd" or "cache stampede" problem).
	res, err, _ := c.group.Do(key, func() (any, error) {
		return c.loadAndStore(context.WithoutCancel(ctx), key)
	})
	if err != nil {
		return "", err
	}
	return res.(string), nil
}

func (c *Cache) loadAndStore(ctx context.Context, key string) (string, error) {
	v, err := c.load(ctx, key)
	if err != nil {
		return "", err
	}
	if err := c.rdb.Set(ctx, c.prefix+key, v, c.ttl).Err(); err != nil {
		c.logger.Warn("cache write failed", "key", key, "error", err)
	}
	return v, nil
}

// Invalidate removes key, for example after the source changed.
func (c *Cache) Invalidate(ctx context.Context, key string) error {
	return c.rdb.Del(ctx, c.prefix+key).Err()
}

// [end cache]

