// Code generated by "stringer -type=Level -trimprefix=Level"; DO NOT EDIT.

package genstringer

import "strconv"

func _() {
	// An "invalid array index" compiler error signifies that the constant values have changed.
	// Re-run the stringer command to generate them again.
	var x [1]struct{}
	_ = x[LevelDebug-0]
	_ = x[LevelInfo-1]
	_ = x[LevelWarn-2]
	_ = x[LevelError-3]
}

const _Level_name = "DebugInfoWarnError"

var _Level_index = [...]uint8{0, 5, 9, 13, 18}

func (i Level) String() string {
	idx := int(i) - 0
	if i < 0 || idx >= len(_Level_index)-1 {
		return "Level(" + strconv.FormatInt(int64(i), 10) + ")"
	}
	return _Level_name[_Level_index[idx]:_Level_index[idx+1]]
}

