func TestUnion(t *testing.T) {
	a := New(1, 2, 3)
	b := New(3, 4)
	u := a.Union(b)
	if got := Sorted(u); !slices.Equal(got, []int{1, 2, 3, 4}) {
		t.Errorf("Union = %v", got)
