func TestTallyConcurrent(t *testing.T) {
	var tally Tally // zero value must work
	var wg sync.WaitGroup
	for i := range 200 {
		wg.Add(1)
		go func() {
			defer wg.Done()
			tally.Add("go")
			if i%2 == 0 {
				tally.Add("rust")
			}
			_ = tally.Count("go") // concurrent reads too
		}()
	}
	wg.Wait()
	if got := tally.Count("go"); got != 200 {
		t.Errorf("go = %d, want 200", got)
