projects/jobqueue/cmd/demo/main.go.content:
// Command demo enqueues a batch of fake email jobs and processes them
// with a pool of workers. One in five sends "fails" the first time, to
// show retries. Run it against any PostgreSQL database:
//
//	DATABASE_URL='postgres://postgres:pg@localhost:5432/postgres?sslmode=disable' go run ./cmd/demo
package main

import (
	"context"
	"encoding/json"
	"errors"
	"fmt"
	"log/slog"
	"os"
	"os/signal"
	"syscall"
	"time"

	"github.com/Priyadharshan0903/gopath-academy/projects/jobqueue"
	"github.com/jackc/pgx/v5/pgxpool"
)

type email struct {
	To      string `json:"to"`
	Subject string `json:"subject"`
}

func main() {
	if err := run(); err != nil {
		fmt.Fprintln(os.Stderr, "demo:", err)
		os.Exit(1)
	}
}

func run() error {
	ctx, stop := signal.NotifyContext(context.Background(), os.Interrupt, syscall.SIGTERM)
	defer stop()
	logger := slog.New(slog.NewTextHandler(os.Stdout, nil))

	pool, err := pgxpool.New(ctx, os.Getenv("DATABASE_URL"))
	if err != nil {
		return err
	}
	defer pool.Close()
	client := jobqueue.New(pool)
	if err := client.Migrate(ctx); err != nil {
		return err
	}

	for i := range 20 {
		_, err := client.Enqueue(ctx, "emails", email{To: fmt.Sprintf("user%d@example.com", i), Subject: "Welcome"}, jobqueue.EnqueueOptions{})
		if err != nil {
			return err
		}
	}

	w := &jobqueue.Worker{
		Client:      client,
		Queue:       "emails",
		Concurrency: 4,
		Backoff:     jobqueue.ExponentialBackoff(200*time.Millisecond, 5*time.Second),
		Logger:      logger,
		Handler: func(ctx context.Context, j jobqueue.Job) error {
			var e email
			if err := json.Unmarshal(j.Payload, &e); err != nil {
				return err
			}
			time.Sleep(100 * time.Millisecond) // "send" the email
			if j.ID%5 == 0 && j.Attempts == 1 {
				return errors.New("smtp: connection reset")
			}
			return nil
		},
	}

	workCtx, cancel := context.WithCancel(ctx)
	go func() {
		for workCtx.Err() == nil {
			time.Sleep(200 * time.Millisecond)
			if c, _ := client.Counts(ctx, "emails"); c["queued"] == 0 && c["running"] == 0 {
				logger.Info("queue empty", "counts", c)
				cancel()
			}
		}
	}()
	return w.Run(workCtx)
}

projects/jobqueue/internal/pgtest/pgtest.content:
// Package pgtest gives each test its own empty PostgreSQL schema.
//
// Tests that need a database call pgtest.URL or pgtest.Pool. They are
// skipped unless TEST_DATABASE_URL is set, for example:
//
//	docker run -d --name pg -e POSTGRES_PASSWORD=pg -p 5432:5432 postgres:16
//	export TEST_DATABASE_URL='postgres://postgres:pg@localhost:5432/postgres?sslmode=disable'
package pgtest

import (
	"context"
	"fmt"
	"net/url"
	"os"
	"strings"
	"testing"

	"github.com/jackc/pgx/v5"
	"github.com/jackc/pgx/v5/pgxpool"
)

// URL creates a fresh schema for t and returns a connection URL whose
// search_path points at it. The schema is dropped when t ends.
func URL(t testing.TB) string {
	t.Helper()
	base := os.Getenv("TEST_DATABASE_URL")
	if base == "" {
		t.Skip("TEST_DATABASE_URL not set; see projects/jobqueue/README.md")
	}
	ctx := context.Background()
	conn, err := pgx.Connect(ctx, base)
	if err != nil {
		t.Fatalf("connect to TEST_DATABASE_URL: %v", err)
	}
	defer conn.Close(ctx)

	// The process ID keeps parallel test binaries (one per package)
	// apart; PostgreSQL identifiers are limited to 63 bytes.
	name := strings.ToLower(strings.NewReplacer("/", "_", "#", "_", " ", "_").Replace(t.Name()))
	if len(name) > 40 {
		name = name[:40]
	}
	schema := pgx.Identifier{fmt.Sprintf("test_%s_%d", name, os.Getpid())}.Sanitize()
	if _, err := conn.Exec(ctx, fmt.Sprintf("DROP SCHEMA IF EXISTS %s CASCADE; CREATE SCHEMA %s", schema, schema)); err != nil {
		t.Fatal(err)
	}
	t.Cleanup(func() {
		c, err := pgx.Connect(context.Background(), base)
		if err == nil {
			c.Exec(context.Background(), "DROP SCHEMA IF EXISTS "+schema+" CASCADE")
			c.Close(context.Background())
		}
	})

	u, err := url.Parse(base)
	if err != nil {
		t.Fatal(err)
	}
	q := u.Query()
	q.Set("search_path", strings.Trim(schema, `"`))
	u.RawQuery = q.Encode()
	return u.String()
}

// Pool returns a pgxpool connected to a fresh schema for t.
func Pool(t testing.TB) *pgxpool.Pool {
	t.Helper()
	pool, err := pgxpool.New(context.Background(), URL(t))
	if err != nil {
		t.Fatal(err)
	}
	t.Cleanup(pool.Close)
	return pool
}

projects/jobqueue/jobqueue_test.go.content:
package jobqueue

import (
	"context"
	"errors"
	"log/slog"
	"sync"
	"sync/atomic"
	"testing"
	"time"

	"github.com/Priyadharshan0903/gopath-academy/projects/jobqueue/internal/pgtest"
)

func newClient(t *testing.T) *Client {
	t.Helper()
	c := New(pgtest.Pool(t))
	if err := c.Migrate(t.Context()); err != nil {
		t.Fatal(err)
	}
	return c
}

// start runs a worker in the background and returns a stop function
// that cancels it and waits for Run to return.
func start(t *testing.T, w *Worker) (stop func()) {
	t.Helper()
	if w.Logger == nil {
		w.Logger = slog.New(slog.DiscardHandler)
	}
	if w.PollInterval == 0 {
		w.PollInterval = 20 * time.Millisecond
	}
	ctx, cancel := context.WithCancel(context.Background())
	done := make(chan struct{})
	go func() { w.Run(ctx); close(done) }()
	return func() { cancel(); <-done }
}

// waitFor polls Counts until cond holds or 10 seconds pass.
func waitFor(t *testing.T, c *Client, queue string, cond func(map[string]int) bool) map[string]int {
	t.Helper()
	deadline := time.Now().Add(10 * time.Second)
	for {
		counts, err := c.Counts(t.Context(), queue)
		if err != nil {
			t.Fatal(err)
		}
		if cond(counts) {
			return counts
		}
		if time.Now().After(deadline) {
			t.Fatalf("timed out; counts = %v", counts)
		}
		time.Sleep(20 * time.Millisecond)
	}
}

// [start exactlyonce]

func TestEveryJobProcessedOnce(t *testing.T) {
	c := newClient(t)
	const n = 200
	for i := range n {
		if _, err := c.Enqueue(t.Context(), "emails", map[string]int{"n": i}, EnqueueOptions{}); err != nil {
			t.Fatal(err)
		}
	}

	var mu sync.Mutex
	seen := map[int64]int{}
	stop := start(t, &Worker{Client: c, Queue: "emails", Concurrency: 8, Handler: func(ctx context.Context, j Job) error {
		mu.Lock()
		seen[j.ID]++
		mu.Unlock()
		return nil
	}})
	begin := time.Now()
	waitFor(t, c, "emails", func(m map[string]int) bool { return m["done"] == n })
	stop()

	t.Logf("8 workers processed %d jobs in %v", n, time.Since(begin).Round(time.Millisecond))
	if len(seen) != n {
		t.Fatalf("processed %d distinct jobs, want %d", len(seen), n)
	}
	for id, times := range seen {
		if times != 1 {
			t.Errorf("job %d processed %d times", id, times)
		}
	}
}

// [end exactlyonce]

func TestRetryThenSucceed(t *testing.T) {
	c := newClient(t)
	id, _ := c.Enqueue(t.Context(), "q", "flaky", EnqueueOptions{})
	var attempts atomic.Int64
	stop := start(t, &Worker{Client: c, Queue: "q", Backoff: func(int) time.Duration { return 0 },
		Handler: func(ctx context.Context, j Job) error {
			if attempts.Add(1) < 3 {
				return errors.New("temporarily unavailable")
			}
			return nil
		}})
	defer stop()
	waitFor(t, c, "q", func(m map[string]int) bool { return m["done"] == 1 })

	var got int
	var lastErr string
	c.pool.QueryRow(t.Context(), `SELECT attempts, last_error FROM jobs WHERE id = $1`, id).Scan(&got, &lastErr)
	if got != 3 || lastErr != "temporarily unavailable" {
		t.Fatalf("attempts=%d last_error=%q, want 3 and the last failure", got, lastErr)
	}
}

func TestGivesUpAfterMaxAttempts(t *testing.T) {
	c := newClient(t)
	c.Enqueue(t.Context(), "q", "doomed", EnqueueOptions{MaxAttempts: 3})
	var calls atomic.Int64
	stop := start(t, &Worker{Client: c, Queue: "q", Backoff: func(int) time.Duration { return 0 },
		Handler: func(ctx context.Context, j Job) error {
			calls.Add(1)
			panic("bad payload") // panics are failures too
		}})
	defer stop()
	waitFor(t, c, "q", func(m map[string]int) bool { return m["failed"] == 1 })
	if calls.Load() != 3 {
		t.Fatalf("handler called %d times, want 3", calls.Load())
	}
}

// [start reclaim]

func TestReclaimAfterCrash(t *testing.T) {
	c := newClient(t)
	id, _ := c.Enqueue(t.Context(), "q", "x", EnqueueOptions{})

	// A worker claims the job and then "crashes": it never reports back.
	if _, err := c.claim(t.Context(), "q", 200*time.Millisecond); err != nil {
		t.Fatal(err)
	}

	var gotAttempt atomic.Int64
	stop := start(t, &Worker{Client: c, Queue: "q", Handler: func(ctx context.Context, j Job) error {
		gotAttempt.Store(int64(j.Attempts))
		return nil
	}})
	defer stop()
	begin := time.Now()
	waitFor(t, c, "q", func(m map[string]int) bool { return m["done"] == 1 })
	t.Logf("job %d reclaimed after %v, on attempt %d", id, time.Since(begin).Round(10*time.Millisecond), gotAttempt.Load())
	if gotAttempt.Load() != 2 {
		t.Fatalf("attempt = %d, want 2", gotAttempt.Load())
	}
}

// [end reclaim]

// [start txenqueue]

func TestEnqueueInTransaction(t *testing.T) {
	c := newClient(t)
	ctx := t.Context()

	tx, _ := c.pool.Begin(ctx)
	EnqueueWith(ctx, tx, "q", "rolled back", EnqueueOptions{})
	tx.Rollback(ctx)

	tx, _ = c.pool.Begin(ctx)
	EnqueueWith(ctx, tx, "q", "committed", EnqueueOptions{})
	tx.Commit(ctx)

	counts, _ := c.Counts(ctx, "q")
	if counts["queued"] != 1 {
		t.Fatalf("counts = %v, want exactly the committed job", counts)
	}
}

// [end txenqueue]

func TestDelay(t *testing.T) {
	c := newClient(t)
	c.Enqueue(t.Context(), "q", "later", EnqueueOptions{Delay: 300 * time.Millisecond})
	var ranAt atomic.Int64
	enqueued := time.Now()
	stop := start(t, &Worker{Client: c, Queue: "q", Handler: func(ctx context.Context, j Job) error {
		ranAt.Store(int64(time.Since(enqueued)))
		return nil
	}})
	defer stop()
	waitFor(t, c, "q", func(m map[string]int) bool { return m["done"] == 1 })
	if d := time.Duration(ranAt.Load()); d < 300*time.Millisecond {
		t.Fatalf("ran after %v, before its delay", d)
	}
}

// [start shutdown]

func TestShutdownWaitsForRunningJobs(t *testing.T) {
	c := newClient(t)
	c.Enqueue(t.Context(), "q", "slow", EnqueueOptions{})
	started := make(chan struct{})
	stop := start(t, &Worker{Client: c, Queue: "q", Handler: func(ctx context.Context, j Job) error {
		close(started)
		time.Sleep(300 * time.Millisecond)
		return nil
	}})

	<-started
	begin := time.Now()
	stop() // cancel while the job is running
	t.Logf("Run returned %v after cancel", time.Since(begin).Round(10*time.Millisecond))

	counts, _ := c.Counts(t.Context(), "q")
	if counts["done"] != 1 {
		t.Fatalf("counts = %v: the running job should have finished", counts)
	}
}

// [end shutdown]

projects/jobqueue/jobqueue.go.content:
// Package jobqueue is a background job queue stored in PostgreSQL.
//
// Producers enqueue jobs, possibly inside their own database
// transaction. Workers claim jobs with SELECT ... FOR UPDATE SKIP
// LOCKED, run a handler, and mark each job done, or schedule a retry
// with backoff, or give up after MaxAttempts. A job whose worker
// crashed is picked up again once its lock expires.
//
// Delivery is at least once: handlers must be idempotent.
package jobqueue

import (
	"context"
	_ "embed"
	"encoding/json"
	"fmt"
	"time"

	"github.com/jackc/pgx/v5"
	"github.com/jackc/pgx/v5/pgxpool"
)

//go:embed schema.sql
var schema string

// Job is one unit of work.
type Job struct {
	ID          int64
	Queue       string
	Payload     json.RawMessage
	Attempts    int // including the current one
	MaxAttempts int
	LastError   string
}

// Client enqueues jobs and inspects the queue.
type Client struct {
	pool *pgxpool.Pool
}

// New returns a Client. Call Migrate once before use.
func New(pool *pgxpool.Pool) *Client { return &Client{pool: pool} }

// Migrate creates the jobs table if it does not exist.
func (c *Client) Migrate(ctx context.Context) error {
	_, err := c.pool.Exec(ctx, schema)
	return err
}

// [start enqueue]

// EnqueueOptions control a single job.
type EnqueueOptions struct {
	Delay       time.Duration // run no earlier than this from now
	MaxAttempts int           // default 5
}

// Executor is satisfied by *pgxpool.Pool, *pgx.Conn and pgx.Tx.
type Executor interface {
	QueryRow(ctx context.Context, sql string, args ...any) pgx.Row
}

// Enqueue adds a job and returns its ID.
func (c *Client) Enqueue(ctx context.Context, queue string, payload any, opts EnqueueOptions) (int64, error) {
	return EnqueueWith(ctx, c.pool, queue, payload, opts)
}

// EnqueueWith adds a job using db, which can be a transaction: the job
// then exists only if the transaction commits. "Create the order and
// enqueue the confirmation email" becomes one atomic step, the main
// advantage of keeping a queue in the database you already use.
func EnqueueWith(ctx context.Context, db Executor, queue string, payload any, opts EnqueueOptions) (int64, error) {
	b, err := json.Marshal(payload)
	if err != nil {
		return 0, fmt.Errorf("encode payload: %w", err)
	}
	if opts.MaxAttempts <= 0 {
		opts.MaxAttempts = 5
	}
	var id int64
	err = db.QueryRow(ctx,
		`INSERT INTO jobs (queue, payload, max_attempts, run_at)
		 VALUES ($1, $2, $3, now() + make_interval(secs => $4))
		 RETURNING id`,
		queue, b, opts.MaxAttempts, opts.Delay.Seconds()).Scan(&id)
	return id, err
}

// [end enqueue]

// Counts returns the number of jobs in each status for a queue.
func (c *Client) Counts(ctx context.Context, queue string) (map[string]int, error) {
	rows, err := c.pool.Query(ctx, `SELECT status, count(*) FROM jobs WHERE queue = $1 GROUP BY status`, queue)
	if err != nil {
		return nil, err
	}
	out := map[string]int{}
	var status string
	var n int
	_, err = pgx.ForEachRow(rows, []any{&status, &n}, func() error {
		out[status] = n
		return nil
	})
	return out, err
}

// [start claim]

// claim locks the next runnable job in queue for visibility, or returns
// pgx.ErrNoRows if there is none. Runnable means queued and due, or
// running with an expired lock (its worker died).
//
// SKIP LOCKED is what makes this a queue: concurrent workers skip rows
// another transaction has locked, instead of waiting for them, so each
// job is claimed by exactly one worker.
func (c *Client) claim(ctx context.Context, queue string, visibility time.Duration) (Job, error) {
	var j Job
	var lastErr *string
	err := c.pool.QueryRow(ctx, `
		UPDATE jobs
		   SET status = 'running', attempts = attempts + 1,
		       locked_until = now() + make_interval(secs => $2), updated_at = now()
		 WHERE id = (
		       SELECT id FROM jobs
		        WHERE queue = $1
		          AND (status = 'queued' AND run_at <= now()
		               OR status = 'running' AND locked_until < now())
		        ORDER BY run_at, id
		        LIMIT 1
		          FOR UPDATE SKIP LOCKED)
		RETURNING id, queue, payload, attempts, max_attempts, last_error`,
		queue, visibility.Seconds(),
	).Scan(&j.ID, &j.Queue, &j.Payload, &j.Attempts, &j.MaxAttempts, &lastErr)
	if lastErr != nil {
		j.LastError = *lastErr
	}
	return j, err
}

// [end claim]

// [start finish]

// complete marks a job done. The attempts check makes sure we still own
// the job: if our lock expired and another worker claimed it, attempts
// has changed and this update does nothing.
func (c *Client) complete(ctx context.Context, j Job) error {
	_, err := c.pool.Exec(ctx,
		`UPDATE jobs SET status = 'done', locked_until = NULL, updated_at = now()
		  WHERE id = $1 AND attempts = $2`, j.ID, j.Attempts)
	return err
}

// fail records a failed attempt: retry after backoff, or give up.
func (c *Client) fail(ctx context.Context, j Job, cause error, backoff time.Duration) error {
	status := "queued"
	if j.Attempts >= j.MaxAttempts {
		status = "failed"
	}
	_, err := c.pool.Exec(ctx,
		`UPDATE jobs SET status = $3, last_error = $4, locked_until = NULL,
		        run_at = now() + make_interval(secs => $5), updated_at = now()
		  WHERE id = $1 AND attempts = $2`,
		j.ID, j.Attempts, status, cause.Error(), backoff.Seconds())
	return err
}

// [end finish]

projects/jobqueue/worker.go.content:
package jobqueue

import (
	"context"
	"errors"
	"fmt"
	"log/slog"
	"math/rand/v2"
	"sync"
	"time"

	"github.com/jackc/pgx/v5"
)

// A Handler processes one job. Returning an error schedules a retry.
// The context is cancelled when the job's lock is about to expire.
type Handler func(ctx context.Context, j Job) error

// Worker runs a handler for the jobs of one queue.
type Worker struct {
	Client       *Client
	Queue        string
	Handler      Handler
	Concurrency  int                             // goroutines processing jobs, default 4
	PollInterval time.Duration                   // wait when the queue is empty, default 1s
	Visibility   time.Duration                   // how long a claimed job stays locked, default 1m
	Backoff      func(attempt int) time.Duration // delay before retry n, default exponential
	Logger       *slog.Logger
}

// [start run]

// Run processes jobs until ctx is cancelled. It then stops claiming new
// jobs, waits for the jobs in progress to finish, and returns.
func (w *Worker) Run(ctx context.Context) error {
	w.defaults()
	var wg sync.WaitGroup
	for range w.Concurrency {
		wg.Go(func() { w.loop(ctx) })
	}
	wg.Wait()
	return nil
}

func (w *Worker) loop(ctx context.Context) {
	for ctx.Err() == nil {
		// The claim itself is not cancelled by shutdown: a claim that
		// commits after we gave up waiting would leave a job locked
		// until its visibility timeout.
		claimCtx, cancel := context.WithTimeout(context.WithoutCancel(ctx), 10*time.Second)
		j, err := w.Client.claim(claimCtx, w.Queue, w.Visibility)
		cancel()
		switch {
		case errors.Is(err, pgx.ErrNoRows):
			// Nothing to do: wait, with jitter so idle workers do not
			// poll in lockstep.
			sleep(ctx, w.PollInterval/2+rand.N(w.PollInterval))
		case err != nil:
			w.Logger.Error("claim failed", "queue", w.Queue, "error", err)
			sleep(ctx, w.PollInterval)
		default:
			w.process(j)
		}
	}
}

// process runs one job. It deliberately does not use the Run context:
// shutting down must let a running job finish. Its own deadline is the
// end of its lock, after which another worker may claim it.
func (w *Worker) process(j Job) {
	ctx, cancel := context.WithTimeout(context.Background(), w.Visibility)
	defer cancel()

	if j.Attempts > j.MaxAttempts { // a worker crashed during the last allowed attempt
		w.finish(j, w.Client.fail(ctx, j, errors.New("worker stopped during the final attempt"), 0))
		return
	}
	start := time.Now()
	err := safeCall(ctx, w.Handler, j)
	if err == nil {
		w.finish(j, w.Client.complete(ctx, j))
		w.Logger.Info("job done", "id", j.ID, "attempt", j.Attempts, "duration", time.Since(start))
		return
	}
	w.Logger.Warn("job failed", "id", j.ID, "attempt", j.Attempts, "max_attempts", j.MaxAttempts, "error", err)
	w.finish(j, w.Client.fail(ctx, j, err, w.Backoff(j.Attempts)))
}

// [end run]

func (w *Worker) finish(j Job, err error) {
	if err != nil {
		w.Logger.Error("could not record job result", "id", j.ID, "error", err)
	}
}

// safeCall runs the handler and turns a panic into an error, so one bad
// job cannot crash the worker process.
func safeCall(ctx context.Context, h Handler, j Job) (err error) {
	defer func() {
		if v := recover(); v != nil {
			err = fmt.Errorf("panic: %v", v)
		}
	}()
	return h(ctx, j)
}

func sleep(ctx context.Context, d time.Duration) {
	t := time.NewTimer(d)
	defer t.Stop()
	select {
	case <-ctx.Done():
	case <-t.C:
	}
}

func (w *Worker) defaults() {
	if w.Concurrency <= 0 {
		w.Concurrency = 4
	}
	if w.PollInterval <= 0 {
		w.PollInterval = time.Second
	}
	if w.Visibility <= 0 {
		w.Visibility = time.Minute
	}
	if w.Backoff == nil {
		w.Backoff = ExponentialBackoff(time.Second, time.Hour)
	}
	if w.Logger == nil {
		w.Logger = slog.Default()
	}
}

// ExponentialBackoff doubles the delay after each attempt, from base up
// to limit, with up to 20% random jitter.
func ExponentialBackoff(base, limit time.Duration) func(int) time.Duration {
	return func(attempt int) time.Duration {
		d := base << min(attempt-1, 30)
		if d <= 0 || d > limit {
			d = limit
		}
		return d + rand.N(d/5+1)
	}
}

