// Package resp reads and writes RESP2, the Redis serialization protocol.
//
// Clients send commands as arrays of bulk strings:
//
//	*2\r\n$3\r\nGET\r\n$4\r\nname\r\n     ->  ["GET", "name"]
//
// Servers reply with one of five types:
//
//	+OK\r\n            simple string
//	-ERR message\r\n   error
//	:42\r\n            integer
//	$5\r\nhello\r\n    bulk string ($-1\r\n is null)
//	*N\r\n...          array of N replies
package resp

import (
	"bufio"
	"errors"
	"fmt"
	"io"
	"strconv"
	"strings"
)

// ErrProtocol is wrapped by every error caused by malformed input.
var ErrProtocol = errors.New("protocol error")

// Limits that protect the server from huge or malicious requests.
const (
	maxArgs     = 1024
	maxBulkSize = 512 * 1024 * 1024 // Redis' own limit for a bulk string
	maxLineSize = 64 * 1024
)

// Reader parses commands from a client connection.
type Reader struct {
	br *bufio.Reader
}

// NewReader wraps r with buffering.
func NewReader(r io.Reader) *Reader { return &Reader{br: bufio.NewReaderSize(r, 16*1024)} }

// ReadCommand reads one command. It accepts the standard array form
// and the "inline" form (plain text like "PING\r\n") that telnet and
// redis-cli in some modes send. It returns io.EOF when the client
// disconnects cleanly between commands.
func (r *Reader) ReadCommand() ([]string, error) {
	line, err := r.readLine()
	if err != nil {
		return nil, err
	}
	if len(line) == 0 {
		return r.ReadCommand() // skip empty lines
	}
	if line[0] != '*' {
		return strings.Fields(line), nil // inline command
	}

	n, err := strconv.Atoi(line[1:])
	if err != nil || n < 0 || n > maxArgs {
		return nil, fmt.Errorf("%w: invalid array length %q", ErrProtocol, line)
	}
	args := make([]string, 0, n)
	for range n {
		arg, err := r.readBulk()
		if err != nil {
			return nil, err
		}
		args = append(args, arg)
	}
	return args, nil
}

func (r *Reader) readBulk() (string, error) {
	line, err := r.readLine()
	if err != nil {
		return "", noEOF(err)
	}
	if len(line) == 0 || line[0] != '$' {
		return "", fmt.Errorf("%w: expected bulk string, got %q", ErrProtocol, line)
	}
	size, err := strconv.Atoi(line[1:])
	if err != nil || size < 0 || size > maxBulkSize {
		return "", fmt.Errorf("%w: invalid bulk length %q", ErrProtocol, line)
	}
	buf := make([]byte, size+2) // payload plus \r\n
	if _, err := io.ReadFull(r.br, buf); err != nil {
		return "", noEOF(err)
	}
	if buf[size] != '\r' || buf[size+1] != '\n' {
		return "", fmt.Errorf("%w: bulk string not terminated by CRLF", ErrProtocol)
	}
	return string(buf[:size]), nil
}

// readLine reads up to \r\n (a bare \n is accepted for inline commands).
func (r *Reader) readLine() (string, error) {
	line, err := r.br.ReadSlice('\n')
	if errors.Is(err, bufio.ErrBufferFull) || len(line) > maxLineSize {
		return "", fmt.Errorf("%w: line too long", ErrProtocol)
	}
	if err != nil {
		if errors.Is(err, io.EOF) && len(line) > 0 {
			return "", io.ErrUnexpectedEOF
		}
		return "", err
	}
	return strings.TrimSuffix(strings.TrimSuffix(string(line), "\n"), "\r"), nil
}

// noEOF turns io.EOF in the middle of a command into ErrUnexpectedEOF.
func noEOF(err error) error {
	if errors.Is(err, io.EOF) {
		return io.ErrUnexpectedEOF
	}
	return err
}

// Writer writes replies. Call Flush after each reply (or batch).
type Writer struct {
	bw *bufio.Writer
}

// NewWriter wraps w with buffering.
func NewWriter(w io.Writer) *Writer { return &Writer{bw: bufio.NewWriter(w)} }

// Simple writes a simple string such as OK or PONG.
func (w *Writer) Simple(s string) { w.bw.WriteString("+" + s + "\r\n") }

// Error writes an error reply. By convention it starts with a code such as ERR.
func (w *Writer) Error(msg string) { w.bw.WriteString("-" + msg + "\r\n") }

// Int writes an integer reply.
func (w *Writer) Int(n int64) {
	w.bw.WriteByte(':')
	w.bw.WriteString(strconv.FormatInt(n, 10))
	w.bw.WriteString("\r\n")
}

// Bulk writes a bulk string reply.
func (w *Writer) Bulk(s string) {
	w.bw.WriteByte('$')
	w.bw.WriteString(strconv.Itoa(len(s)))
	w.bw.WriteString("\r\n")
	w.bw.WriteString(s)
	w.bw.WriteString("\r\n")
}

// Null writes the null bulk string, used for missing keys.
func (w *Writer) Null() { w.bw.WriteString("$-1\r\n") }

// Array writes an array of bulk strings, the format commands use.
func (w *Writer) Array(items []string) {
	w.bw.WriteByte('*')
	w.bw.WriteString(strconv.Itoa(len(items)))
	w.bw.WriteString("\r\n")
	for _, it := range items {
		w.Bulk(it)
	}
}

// Flush sends buffered data to the underlying writer.
func (w *Writer) Flush() error { return w.bw.Flush() }

projects/miniredis/internal/server/apply.content:
package server

import (
	"errors"
	"strings"

	"github.com/Priyadharshan0903/gopath-academy/projects/miniredis/internal/resp"
)

// Apply executes a command without a client connection, for example
// while replaying the append-only file. It returns an error if the
// command produced an error reply.
func (s *Server) Apply(args []string) error {
	var reply strings.Builder
	w := resp.NewWriter(&reply)
	s.execute(args, w)
	w.Flush()
	if strings.HasPrefix(reply.String(), "-") {
		return errors.New(strings.TrimSpace(strings.TrimPrefix(reply.String(), "-")))
	}
	return nil
}

projects/miniredis/internal/server/serve.content:
package server

import (
	"bufio"
	"context"
	"fmt"
	"net"
	"strings"
	"sync"
	"testing"
	"time"

	"github.com/Priyadharshan0903/gopath-academy/projects/miniredis/internal/resp"
	"github.com/Priyadharshan0903/gopath-academy/projects/miniredis/internal/store"
)

// startServer runs a server on a random local port and stops it at the
// end of the test.
func startServer(t *testing.T, aof Appender) string {
	t.Helper()
	ln, err := net.Listen("tcp", "127.0.0.1:0")
	if err != nil {
		t.Fatal(err)
	}
	ctx, cancel := context.WithCancel(context.Background())
	srv := &Server{Store: store.New(), AOF: aof}
	done := make(chan error, 1)
	go func() { done <- srv.Serve(ctx, ln) }()
	t.Cleanup(func() {
		cancel()
		if err := <-done; err != nil {
			t.Errorf("Serve: %v", err)
		}
	})
	return ln.Addr().String()
}

// client is a minimal Redis client for tests.
type client struct {
	conn net.Conn
	r    *bufio.Reader
	w    *resp.Writer
}

func dial(t *testing.T, addr string) *client {
	t.Helper()
	c, err := net.Dial("tcp", addr)
	if err != nil {
		t.Fatal(err)
	}
	t.Cleanup(func() { c.Close() })
	return &client{conn: c, r: bufio.NewReader(c), w: resp.NewWriter(c)}
}

// do sends a command and returns the raw reply line(s) as one string.
func (c *client) do(t *testing.T, args ...string) string {
	t.Helper()
	c.conn.SetDeadline(time.Now().Add(2 * time.Second))
	c.w.Array(args)
	if err := c.w.Flush(); err != nil {
		t.Fatal(err)
	}
	line, err := c.r.ReadString('\n')
	if err != nil {
		t.Fatal(err)
	}
	if strings.HasPrefix(line, "$") && line != "$-1\r\n" {
		body, _ := c.r.ReadString('\n')
		return strings.TrimSpace(body)
	}
	return strings.TrimSpace(line)
}

func TestCommands(t *testing.T) {
	c := dial(t, startServer(t, nil))
	steps := []struct {
		args []string
		want string
	}{
		{[]string{"PING"}, "+PONG"},
		{[]string{"ping", "hello"}, "hello"},
		{[]string{"SET", "name", "Ana Maria"}, "+OK"},
		{[]string{"GET", "name"}, "Ana Maria"},
		{[]string{"GET", "missing"}, "$-1"},
		{[]string{"INCR", "hits"}, ":1"},
		{[]string{"INCR", "hits"}, ":2"},
		{[]string{"INCR", "name"}, "-ERR value is not an integer or out of range"},
		{[]string{"EXISTS", "name", "hits", "nope"}, ":2"},
		{[]string{"SET", "tmp", "x", "EX", "100"}, "+OK"},
		{[]string{"TTL", "tmp"}, ":100"},
		{[]string{"TTL", "name"}, ":-1"},
		{[]string{"DEL", "name", "nope"}, ":1"},
		{[]string{"DBSIZE"}, ":2"},
		{[]string{"GET"}, "-ERR wrong number of arguments for 'get' command"},
		{[]string{"FLY"}, "-ERR unknown command 'FLY'"},
	}
	for _, s := range steps {
		if got := c.do(t, s.args...); got != s.want {
			t.Errorf("%q -> %q, want %q", s.args, got, s.want)
		}
	}
}

func TestInlineCommand(t *testing.T) {
	addr := startServer(t, nil)
	conn, err := net.Dial("tcp", addr)
	if err != nil {
		t.Fatal(err)
	}
	defer conn.Close()
	fmt.Fprint(conn, "PING\r\n") // what you would type in telnet
	line, _ := bufio.NewReader(conn).ReadString('\n')
	if line != "+PONG\r\n" {
		t.Errorf("inline PING -> %q", line)
	}
}

func TestManyConcurrentClients(t *testing.T) {
	addr := startServer(t, nil)
	var wg sync.WaitGroup
	for range 20 {
		wg.Add(1)
		go func() {
			defer wg.Done()
			c := dial(t, addr)
			for range 50 {
				c.do(t, "INCR", "shared")
			}
		}()
	}
	wg.Wait()
	if got := dial(t, addr).do(t, "GET", "shared"); got != "1000" {
		t.Errorf("shared counter = %s, want 1000", got)
	}
}

type recorder struct {
	mu   sync.Mutex
	cmds []string
}

func (r *recorder) Append(args []string) error {
	r.mu.Lock()
	defer r.mu.Unlock()
	r.cmds = append(r.cmds, strings.Join(args, " "))
	return nil
}

func TestOnlyWritesArePersisted(t *testing.T) {
	rec := &recorder{}
	c := dial(t, startServer(t, rec))
	c.do(t, "SET", "a", "1")
	c.do(t, "GET", "a")
	c.do(t, "DEL", "nope") // deleted nothing: not persisted
	c.do(t, "INCR", "n")
	rec.mu.Lock()
	defer rec.mu.Unlock()
	want := []string{"SET a 1", "INCR n"}
	if strings.Join(rec.cmds, "|") != strings.Join(want, "|") {
		t.Errorf("persisted %q, want %q", rec.cmds, want)
	}
}

func TestShutdownClosesClients(t *testing.T) {
	ln, _ := net.Listen("tcp", "127.0.0.1:0")
	ctx, cancel := context.WithCancel(context.Background())
	done := make(chan error, 1)
	go func() { done <- (&Server{Store: store.New()}).Serve(ctx, ln) }()

	c := dial(t, ln.Addr().String())
	c.do(t, "PING") // connected and idle

	cancel()
	select {
	case err := <-done:
		if err != nil {
			t.Fatal(err)
		}
	case <-time.After(2 * time.Second):
		t.Fatal("Serve did not return: idle clients blocked shutdown")
	}
}

// Package server accepts TCP connections and executes Redis commands
// against a store, one goroutine per client.
package server

import (
	"context"
	"errors"
	"fmt"
	"io"
	"log/slog"
	"net"
	"strconv"
	"strings"
	"sync"
	"time"

	"github.com/Priyadharshan0903/gopath-academy/projects/miniredis/internal/resp"
	"github.com/Priyadharshan0903/gopath-academy/projects/miniredis/internal/store"
)

// Appender persists write commands. *aof.Log satisfies it.
type Appender interface {
	Append(args []string) error
}

// Server is a tiny Redis-compatible server.
type Server struct {
	Store  *store.Store
	AOF    Appender     // optional
	Logger *slog.Logger // optional

	mu    sync.Mutex
	conns map[net.Conn]struct{}
	wg    sync.WaitGroup
}

// Serve accepts connections on ln until ctx is cancelled, then closes
// every client connection and waits for their goroutines to finish.
func (s *Server) Serve(ctx context.Context, ln net.Listener) error {
	if s.Logger == nil {
		s.Logger = slog.New(slog.DiscardHandler)
	}
	s.mu.Lock()
	s.conns = make(map[net.Conn]struct{})
	s.mu.Unlock()

	// Closing the listener is what unblocks Accept on shutdown.
	stop := context.AfterFunc(ctx, func() { ln.Close() })
	defer stop()

	for {
		conn, err := ln.Accept()
		if err != nil {
			if ctx.Err() != nil {
				break // shutting down
			}
			var ne net.Error
			if errors.As(err, &ne) && ne.Timeout() {
				time.Sleep(10 * time.Millisecond) // temporary: back off and retry
				continue
			}
			return err
		}
		s.track(conn, true)
		s.wg.Add(1)
		go func() {
			defer s.wg.Done()
			defer s.track(conn, false)
			s.handle(conn)
		}()
	}

	s.mu.Lock()
	for c := range s.conns {
		c.Close() // unblocks each handler's read
	}
	s.mu.Unlock()
	s.wg.Wait()
	return nil
}

func (s *Server) track(c net.Conn, add bool) {
	s.mu.Lock()
	defer s.mu.Unlock()
	if add {
		s.conns[c] = struct{}{}
	} else {
		delete(s.conns, c)
		c.Close()
	}
}

// handle serves one client until it disconnects.
func (s *Server) handle(conn net.Conn) {
	defer func() {
		if r := recover(); r != nil { // a bug in one command must not crash the server
			s.Logger.Error("panic in connection handler", "remote", conn.RemoteAddr(), "panic", r)
		}
	}()
	r := resp.NewReader(conn)
	w := resp.NewWriter(conn)
	for {
		args, err := r.ReadCommand()
		if err != nil {
			if errors.Is(err, resp.ErrProtocol) {
				w.Error("ERR " + err.Error())
				w.Flush()
			}
			if !errors.Is(err, io.EOF) && !errors.Is(err, net.ErrClosed) {
				s.Logger.Debug("connection closed", "remote", conn.RemoteAddr(), "err", err)
			}
			return
		}
		if len(args) == 0 {
			continue
		}
		s.execute(args, w)
		if err := w.Flush(); err != nil {
			return
		}
	}
}

// execute runs one command and writes its reply.
func (s *Server) execute(args []string, w *resp.Writer) {
	cmd := strings.ToUpper(args[0])
	argc := len(args) - 1
	wrongArgs := func() { w.Error(fmt.Sprintf("ERR wrong number of arguments for '%s' command", strings.ToLower(cmd))) }

	switch cmd {
	case "PING":
		switch argc {
		case 0:
			w.Simple("PONG")
		case 1:
			w.Bulk(args[1])
		default:
			wrongArgs()
		}
	case "ECHO":
		if argc != 1 {
			wrongArgs()
			return
		}
		w.Bulk(args[1])
	case "GET":
		if argc != 1 {
			wrongArgs()
			return
		}
		if v, ok := s.Store.Get(args[1]); ok {
			w.Bulk(v)
		} else {
			w.Null()
		}
	case "SET":
		if argc != 2 && argc != 4 {
			wrongArgs()
			return
		}
		var ttl time.Duration
		if argc == 4 {
			if !strings.EqualFold(args[3], "EX") {
				w.Error("ERR syntax error")
				return
			}
			secs, err := strconv.Atoi(args[4])
			if err != nil || secs <= 0 {
				w.Error("ERR invalid expire time in 'set' command")
				return
			}
			ttl = time.Duration(secs) * time.Second
		}
		s.Store.Set(args[1], args[2], ttl)
		s.persist(args)
		w.Simple("OK")
	case "DEL":
		if argc < 1 {
			wrongArgs()
			return
		}
		n := s.Store.Del(args[1:]...)
		if n > 0 {
			s.persist(args)
		}
		w.Int(int64(n))
	case "EXISTS":
		if argc < 1 {
			wrongArgs()
			return
		}
		w.Int(int64(s.Store.Exists(args[1:]...)))
	case "INCR":
		if argc != 1 {
			wrongArgs()
			return
		}
		n, err := s.Store.Incr(args[1])
		if err != nil {
			w.Error("ERR " + err.Error())
			return
		}
		s.persist(args)
		w.Int(n)
	case "EXPIRE":
		if argc != 2 {
			wrongArgs()
			return
		}
		secs, err := strconv.Atoi(args[2])
		if err != nil {
			w.Error("ERR value is not an integer or out of range")
			return
		}
		if s.Store.Expire(args[1], time.Duration(secs)*time.Second) {
			s.persist(args)
			w.Int(1)
		} else {
			w.Int(0)
		}
	case "TTL":
		if argc != 1 {
			wrongArgs()
			return
		}
		ttl := s.Store.TTL(args[1])
		if ttl < 0 {
			w.Int(int64(ttl)) // -1 or -2
		} else {
			w.Int(int64((ttl + time.Second - 1) / time.Second)) // round up like Redis
		}
	case "DBSIZE":
		w.Int(int64(s.Store.Len()))
	case "COMMAND": // redis-cli asks for this on connect; an empty reply is fine
		w.Array(nil)
	default:
		w.Error(fmt.Sprintf("ERR unknown command '%s'", args[0]))
	}
}

func (s *Server) persist(args []string) {
	if s.AOF == nil {
		return
	}
	if err := s.AOF.Append(args); err != nil {
		s.Logger.Error("aof append failed", "err", err)
	}
}

