func newTestService() *Service {
	s := NewService(NewMemoryStore())
	s.now = func() time.Time { return time.Date(2026, 10, 16, 9, 0, 0, 0, time.UTC) }
	return s
}

func TestShortenAndResolve(t *testing.T) {
	ctx := context.Background()
	s := newTestService()

	l, err := s.Shorten(ctx, "https://go.dev/doc/", "")
	if err != nil {
		t.Fatal(err)
	}
	if len(l.Code) != generatedLength {
		t.Errorf("generated code %q has length %d", l.Code, len(l.Code))
	}
	if !l.CreatedAt.Equal(s.now()) {
		t.Errorf("CreatedAt = %v", l.CreatedAt)
	}

	got, err := s.Resolve(ctx, l.Code)
	if err != nil || got.URL != "https://go.dev/doc/" {
		t.Errorf("Resolve = %+v, %v", got, err)
	}
}

func TestCustomCode(t *testing.T) {
	ctx := context.Background()
	s := newTestService()

	if _, err := s.Shorten(ctx, "https://example.com", "my-link"); err != nil {
		t.Fatal(err)
	}
	_, err := s.Shorten(ctx, "https://other.example", "my-link")
	if !errors.Is(err, ErrCodeTaken) {
		t.Errorf("second Shorten with same code: %v, want ErrCodeTaken", err)
	}
	if !strings.Contains(err.Error(), "my-link") {
		t.Errorf("error should mention the code: %v", err)
	}
}

func TestValidation(t *testing.T) {
	ctx := context.Background()
	s := newTestService()

	badURLs := []string{"", "ftp://example.com", "example.com", "https://", "http://bad host"}
	for _, u := range badURLs {
		if _, err := s.Shorten(ctx, u, ""); !errors.Is(err, ErrInvalidURL) {
			t.Errorf("Shorten(%q) error = %v, want ErrInvalidURL", u, err)
		}
	}
	badCodes := []string{"ab", strings.Repeat("x", 33), "has space", "emoji🙂"}
	for _, c := range badCodes {
		if _, err := s.Shorten(ctx, "https://example.com", c); !errors.Is(err, ErrInvalidCode) {
			t.Errorf("Shorten(code %q) error = %v, want ErrInvalidCode", c, err)
		}
	}
}

func TestResolveMissing(t *testing.T) {
	_, err := newTestService().Resolve(context.Background(), "nope123")
	if !errors.Is(err, ErrNotFound) {
		t.Errorf("Resolve missing = %v, want ErrNotFound", err)
	}
}

func TestRetriesOnCollision(t *testing.T) {
	ctx := context.Background()
	s := newTestService()
	codes := []string{"taken01", "taken01", "fresh01"}
	s.rand = func(int) string {
		c := codes[0]
		codes = codes[1:]
		return c
	}
	if _, err := s.Shorten(ctx, "https://a.example", ""); err != nil {
		t.Fatal(err)
	}
	l, err := s.Shorten(ctx, "https://b.example", "")
	if err != nil || l.Code != "fresh01" {
		t.Errorf("after a collision got %+v, %v; want code fresh01", l, err)
	}
}

func TestGivesUpAfterTooManyCollisions(t *testing.T) {
	ctx := context.Background()
	s := newTestService()
	s.rand = func(int) string { return "always1" }
	s.Shorten(ctx, "https://a.example", "")

	_, err := s.Shorten(ctx, "https://b.example", "")
	if !errors.Is(err, ErrCodeTaken) || !strings.Contains(err.Error(), "attempts") {
		t.Errorf("got %v, want an error mentioning attempts and wrapping ErrCodeTaken", err)
	}
}

func TestRandomCodeAlphabet(t *testing.T) {
	for range 100 {
		c := randomCode(16)
		if strings.ContainsAny(c, "0O1lI") || len(c) != 16 {
			t.Fatalf("bad code %q", c)
		}
	}
}

projects/shortener/internal/link/link.go.content:
// Package link is the core of the URL shortener: the Link type, the
// errors callers can check for, and the Service that creates and
// resolves short links on top of any Store.
//
// It has no knowledge of HTTP or databases. Those live in other
// packages and are added in later milestones of the project.
package link

import (
	"context"
	"crypto/rand"
	"errors"
	"fmt"
	"net/url"
	"time"
)

// Errors that callers can check with errors.Is. The HTTP layer
// (Module 12) maps each of them to a status code.
var (
	ErrNotFound    = errors.New("link not found")
	ErrCodeTaken   = errors.New("code already in use")
	ErrInvalidURL  = errors.New("invalid url")
	ErrInvalidCode = errors.New("invalid code")
)

// Link is a short code pointing at a target URL.
type Link struct {
	Code      string
	URL       string
	CreatedAt time.Time
}

// Store persists links. Implementations must return an error wrapping
// ErrCodeTaken from Create when the code exists, and ErrNotFound from
// Get when it does not.
//
// The context parameter carries cancellation and deadlines; it is
// covered in Module 7. Until then, context.Background() is fine.
type Store interface {
	Create(ctx context.Context, l Link) error
	Get(ctx context.Context, code string) (Link, error)
	// Delete was added in milestone 4, for the Kubernetes operator.
	// It returns an error wrapping ErrNotFound if the code does not exist.
	Delete(ctx context.Context, code string) error
}

// Service implements the shortener's rules on top of a Store.
type Service struct {
	store Store
	now   func() time.Time
	rand  func(n int) string
}

// NewService returns a Service backed by store.
func NewService(store Store) *Service {
	return &Service{store: store, now: time.Now, rand: randomCode}
}

const (
	generatedLength = 7
	maxAttempts     = 5
)

// Shorten creates a link for rawURL. If code is empty, a random code
// is generated; otherwise the requested custom code is used.
func (s *Service) Shorten(ctx context.Context, rawURL, code string) (Link, error) {
	if err := validateURL(rawURL); err != nil {
		return Link{}, err
	}
	if code != "" {
		if err := validateCode(code); err != nil {
			return Link{}, err
		}
		return s.create(ctx, code, rawURL)
	}

	// Random codes can collide. Collisions are rare, so retry a few
	// times and only then give up.
	var err error
	for range maxAttempts {
		var l Link
		l, err = s.create(ctx, s.rand(generatedLength), rawURL)
		if !errors.Is(err, ErrCodeTaken) {
			return l, err
		}
	}
	return Link{}, fmt.Errorf("generate code after %d attempts: %w", maxAttempts, err)
}

func (s *Service) create(ctx context.Context, code, rawURL string) (Link, error) {
	l := Link{Code: code, URL: rawURL, CreatedAt: s.now().UTC()}
	if err := s.store.Create(ctx, l); err != nil {
		return Link{}, fmt.Errorf("create %q: %w", code, err)
	}
	return l, nil
}

// Resolve returns the link for code.
func (s *Service) Resolve(ctx context.Context, code string) (Link, error) {
	if err := validateCode(code); err != nil {
		return Link{}, err
	}
	l, err := s.store.Get(ctx, code)
	if err != nil {
		return Link{}, fmt.Errorf("resolve %q: %w", code, err)
	}
	return l, nil
}

// Delete removes the link for code.
func (s *Service) Delete(ctx context.Context, code string) error {
	if err := validateCode(code); err != nil {
		return err
	}
	if err := s.store.Delete(ctx, code); err != nil {
		return fmt.Errorf("delete %q: %w", code, err)
	}
	return nil
}

func validateURL(raw string) error {
	u, err := url.Parse(raw)
	if err != nil {
		return fmt.Errorf("%w: %v", ErrInvalidURL, err)
	}
	if u.Scheme != "http" && u.Scheme != "https" {
		return fmt.Errorf("%w: scheme must be http or https, got %q", ErrInvalidURL, u.Scheme)
	}
	if u.Host == "" {
		return fmt.Errorf("%w: missing host", ErrInvalidURL)
	}
	return nil
}

func validateCode(code string) error {
	if len(code) < 3 || len(code) > 32 {
		return fmt.Errorf("%w: length must be 3 to 32, got %d", ErrInvalidCode, len(code))
	}
	for _, r := range code {
		ok := r >= 'a' && r <= 'z' || r >= 'A' && r <= 'Z' || r >= '0' && r <= '9' || r == '-' || r == '_'
		if !ok {
			return fmt.Errorf("%w: unexpected character %q", ErrInvalidCode, r)
		}
	}
	return nil
}

const alphabet = "abcdefghijkmnpqrstuvwxyzABCDEFGHJKLMNPQRSTUVWXYZ23456789"

// randomCode returns n characters from an alphabet without look-alike
// characters (no 0/O, 1/l/I), using a cryptographically secure source
// so codes cannot be guessed from earlier ones.
func randomCode(n int) string {
	// Bytes at or above limit are discarded. Without this, the first
	// 256 % len(alphabet) characters would be slightly more likely
	// than the others ("modulo bias").
	const limit = 256 - 256%len(alphabet)
	out := make([]byte, 0, n)
	buf := make([]byte, n*2)
	for len(out) < n {
		rand.Read(buf) // since Go 1.24, Read never returns an error; it crashes the program instead
		for _, b := range buf {
			if int(b) < limit && len(out) < n {
				out = append(out, alphabet[int(b)%len(alphabet)])
			}
		}
	}
	return string(out)
}

projects/shortener/internal/link/linktes.content:
// Package linktest is a conformance test suite for link.Store
// implementations. Every store (memory, Postgres, cached) runs the same
// tests, so they all behave the way link.Service expects.
package linktest

import (
	"context"
	"errors"
	"sync"
	"sync/atomic"
	"testing"
	"time"

	"github.com/Priyadharshan0903/gopath-academy/projects/shortener/internal/link"
)

// Run runs the suite. newStore must return an empty store.
func Run(t *testing.T, newStore func(t *testing.T) link.Store) {
	t.Run("CreateThenGet", func(t *testing.T) {
		s := newStore(t)
		ctx := context.Background()
		want := link.Link{Code: "abc", URL: "https://go.dev", CreatedAt: time.Date(2026, 1, 2, 3, 4, 5, 6000, time.UTC)}
		if err := s.Create(ctx, want); err != nil {
			t.Fatal(err)
		}
		got, err := s.Get(ctx, "abc")
		if err != nil {
			t.Fatal(err)
		}
		// Stores may keep only microseconds (PostgreSQL does) and may
		// return another time zone; Equal compares instants.
		if got.Code != want.Code || got.URL != want.URL || !got.CreatedAt.Equal(want.CreatedAt) {
			t.Fatalf("Get = %+v, want %+v", got, want)
		}
		if got.CreatedAt.Location() != time.UTC {
			t.Errorf("CreatedAt should be in UTC, got %v", got.CreatedAt.Location())
		}
	})

	t.Run("GetMissing", func(t *testing.T) {
		_, err := newStore(t).Get(context.Background(), "nope")
		if !errors.Is(err, link.ErrNotFound) {
			t.Fatalf("err = %v, want ErrNotFound", err)
		}
	})

	t.Run("CreateDuplicate", func(t *testing.T) {
		s := newStore(t)
		ctx := context.Background()
		l := link.Link{Code: "dup", URL: "https://a.example", CreatedAt: time.Now().UTC()}
		if err := s.Create(ctx, l); err != nil {
			t.Fatal(err)
		}
		l.URL = "https://b.example"
		if err := s.Create(ctx, l); !errors.Is(err, link.ErrCodeTaken) {
			t.Fatalf("err = %v, want ErrCodeTaken", err)
		}
		got, _ := s.Get(ctx, "dup")
		if got.URL != "https://a.example" {
			t.Fatalf("the duplicate overwrote the original: %+v", got)
		}
	})

	t.Run("Delete", func(t *testing.T) {
		s := newStore(t)
		ctx := context.Background()
		l := link.Link{Code: "gone", URL: "https://go.dev", CreatedAt: time.Now().UTC()}
		if err := s.Create(ctx, l); err != nil {
			t.Fatal(err)
		}
		if _, err := s.Get(ctx, "gone"); err != nil { // with a cache, this fills it
			t.Fatal(err)
		}
		if err := s.Delete(ctx, "gone"); err != nil {
			t.Fatal(err)
		}
		if _, err := s.Get(ctx, "gone"); !errors.Is(err, link.ErrNotFound) {
			t.Fatalf("Get after Delete: err = %v, want ErrNotFound", err)
		}
		if err := s.Delete(ctx, "gone"); !errors.Is(err, link.ErrNotFound) {
			t.Fatalf("second Delete: err = %v, want ErrNotFound", err)
		}
		if err := s.Create(ctx, l); err != nil {
			t.Fatalf("the code should be free again after Delete: %v", err)
		}
	})

	t.Run("ConcurrentCreateSameCode", func(t *testing.T) {
		s := newStore(t)
		var ok, taken atomic.Int64
		var wg sync.WaitGroup
		for range 20 {
			wg.Go(func() {
				err := s.Create(context.Background(), link.Link{Code: "race", URL: "https://go.dev", CreatedAt: time.Now().UTC()})
				switch {
				case err == nil:
					ok.Add(1)
				case errors.Is(err, link.ErrCodeTaken):
					taken.Add(1)
				default:
					t.Error(err)
				}
			})
		}
		wg.Wait()
		if ok.Load() != 1 || taken.Load() != 19 {
			t.Fatalf("%d succeeded and %d got ErrCodeTaken, want 1 and 19", ok.Load(), taken.Load())
		}
	})
}

projects/shortener/internal/link/memstor.content:
package link_test

import (
	"testing"

	"github.com/Priyadharshan0903/gopath-academy/projects/shortener/internal/link"
	"github.com/Priyadharshan0903/gopath-academy/projects/shortener/internal/link/linktest"
)

func TestMemoryStoreContract(t *testing.T) {
	linktest.Run(t, func(t *testing.T) link.Store { return link.NewMemoryStore() })
}

package link

import (
	"context"
	"sync"
)

// MemoryStore is an in-memory Store, safe for concurrent use.
// It is used in tests and for local development.
type MemoryStore struct {
	mu    sync.RWMutex // locking is covered in Module 6
	links map[string]Link
}

// NewMemoryStore returns an empty MemoryStore.
func NewMemoryStore() *MemoryStore {
	return &MemoryStore{links: make(map[string]Link)}
}

// Create stores l, or returns ErrCodeTaken if its code exists.
func (m *MemoryStore) Create(_ context.Context, l Link) error {
	m.mu.Lock()
	defer m.mu.Unlock()
	if _, exists := m.links[l.Code]; exists {
		return ErrCodeTaken
	}
	m.links[l.Code] = l
	return nil
}

// Get returns the link for code, or ErrNotFound.
func (m *MemoryStore) Get(_ context.Context, code string) (Link, error) {
	m.mu.RLock()
	defer m.mu.RUnlock()
	l, ok := m.links[code]
	if !ok {
		return Link{}, ErrNotFound
	}
	return l, nil
}

// Compile-time check that MemoryStore satisfies Store.
var _ Store = (*MemoryStore)(nil)

// Delete removes the link for code, or returns ErrNotFound.
func (m *MemoryStore) Delete(_ context.Context, code string) error {
	m.mu.Lock()
	defer m.mu.Unlock()
	if _, ok := m.links[code]; !ok {
		return ErrNotFound
	}
	delete(m.links, code)
	return nil
}

