// Package pgtest gives each test its own empty PostgreSQL schema.
//
// Tests that need a database call pgtest.URL or pgtest.Pool. They are
// skipped unless TEST_DATABASE_URL is set, for example:
//
//	docker run -d --name pg -e POSTGRES_PASSWORD=pg -p 5432:5432 postgres:16
//	export TEST_DATABASE_URL='postgres://postgres:pg@localhost:5432/postgres?sslmode=disable'
package pgtest

import (
	"context"
	"fmt"
	"net/url"
	"os"
	"strings"
	"testing"

	"github.com/jackc/pgx/v5"
	"github.com/jackc/pgx/v5/pgxpool"
)

// URL creates a fresh schema for t and returns a connection URL whose
// search_path points at it. The schema is dropped when t ends.
func URL(t testing.TB) string {
	t.Helper()
	base := os.Getenv("TEST_DATABASE_URL")
	if base == "" {
		t.Skip("TEST_DATABASE_URL not set; see projects/shortener/README.md")
	}
	ctx := context.Background()
	conn, err := pgx.Connect(ctx, base)
	if err != nil {
		t.Fatalf("connect to TEST_DATABASE_URL: %v", err)
	}
	defer conn.Close(ctx)

	// The process ID keeps parallel test binaries (one per package)
	// apart; PostgreSQL identifiers are limited to 63 bytes.
	name := strings.ToLower(strings.NewReplacer("/", "_", "#", "_", " ", "_").Replace(t.Name()))
	if len(name) > 40 {
		name = name[:40]
	}
	schema := pgx.Identifier{fmt.Sprintf("test_%s_%d", name, os.Getpid())}.Sanitize()
	if _, err := conn.Exec(ctx, fmt.Sprintf("DROP SCHEMA IF EXISTS %s CASCADE; CREATE SCHEMA %s", schema, schema)); err != nil {
		t.Fatal(err)
	}
	t.Cleanup(func() {
		c, err := pgx.Connect(context.Background(), base)
		if err == nil {
			c.Exec(context.Background(), "DROP SCHEMA IF EXISTS "+schema+" CASCADE")
			c.Close(context.Background())
		}
	})

	u, err := url.Parse(base)
	if err != nil {
		t.Fatal(err)
	}
	q := u.Query()
	q.Set("search_path", strings.Trim(schema, `"`))
	u.RawQuery = q.Encode()
	return u.String()
}

// Pool returns a pgxpool connected to a fresh schema for t.
func Pool(t testing.TB) *pgxpool.Pool {
	t.Helper()
	pool, err := pgxpool.New(context.Background(), URL(t))
	if err != nil {
		t.Fatal(err)
	}
	t.Cleanup(pool.Close)
	return pool
}

projects/shortener/internal/postgres/mig.content:
package postgres

import (
	"context"
	"embed"
	"fmt"
	"io/fs"
	"path"
	"slices"

	"github.com/jackc/pgx/v5"
	"github.com/jackc/pgx/v5/pgxpool"
)

// The SQL files are compiled into the binary, so a deployment is one
// file and the code can never run against migrations from another
// version.
//
//go:embed migrations/*.sql
var migrations embed.FS

// migrationLock is an arbitrary number identifying our advisory lock.
const migrationLock = 727_001

// Migrate applies every migration that has not been applied yet, in
// file name order, and returns the names of those it applied.
//
// All of it runs in one transaction (PostgreSQL can roll back schema
// changes), holding an advisory lock, so several replicas starting at
// the same time cannot apply a migration twice.
func Migrate(ctx context.Context, pool *pgxpool.Pool) ([]string, error) {
	files, err := fs.Glob(migrations, "migrations/*.sql")
	if err != nil {
		return nil, err
	}
	slices.Sort(files)

	var applied []string
	err = pgx.BeginFunc(ctx, pool, func(tx pgx.Tx) error {
		if _, err := tx.Exec(ctx, `SELECT pg_advisory_xact_lock($1)`, migrationLock); err != nil {
			return err
		}
		if _, err := tx.Exec(ctx, `CREATE TABLE IF NOT EXISTS schema_migrations (
			version    text PRIMARY KEY,
			applied_at timestamptz NOT NULL DEFAULT now())`); err != nil {
			return err
		}
		rows, err := tx.Query(ctx, `SELECT version FROM schema_migrations`)
		if err != nil {
			return err
		}
		done, err := pgx.CollectRows(rows, pgx.RowTo[string])
		if err != nil {
			return err
		}

		for _, f := range files {
			version := path.Base(f)
			if slices.Contains(done, version) {
				continue
			}
			sql, err := migrations.ReadFile(f)
			if err != nil {
				return err
			}
			if _, err := tx.Exec(ctx, string(sql)); err != nil {
				return fmt.Errorf("migration %s: %w", version, err)
			}
			if _, err := tx.Exec(ctx, `INSERT INTO schema_migrations (version) VALUES ($1)`, version); err != nil {
				return err
			}
			applied = append(applied, version)
		}
		return nil
	})
	return applied, err
}

projects/shortener/internal/postgres/sto.content:
package postgres

import (
	"context"
	"sync"
	"testing"

	"github.com/Priyadharshan0903/gopath-academy/projects/shortener/internal/link"
	"github.com/Priyadharshan0903/gopath-academy/projects/shortener/internal/link/linktest"
	"github.com/Priyadharshan0903/gopath-academy/projects/shortener/internal/pgtest"
)

func TestStoreContract(t *testing.T) {
	linktest.Run(t, func(t *testing.T) link.Store {
		pool := pgtest.Pool(t)
		if _, err := Migrate(context.Background(), pool); err != nil {
			t.Fatal(err)
		}
		return NewStore(pool)
	})
}

func TestMigrateIsIdempotent(t *testing.T) {
	pool := pgtest.Pool(t)
	first, err := Migrate(t.Context(), pool)
	if err != nil || len(first) == 0 {
		t.Fatalf("first run applied %v, err %v", first, err)
	}
	second, err := Migrate(t.Context(), pool)
	if err != nil || len(second) != 0 {
		t.Fatalf("second run applied %v, err %v; want nothing", second, err)
	}
	t.Logf("applied %v, then nothing", first)
}

// Several replicas starting at once must not apply a migration twice.
func TestMigrateConcurrently(t *testing.T) {
	pool := pgtest.Pool(t)
	var mu sync.Mutex
	total := 0
	var wg sync.WaitGroup
	for range 5 {
		wg.Go(func() {
			applied, err := Migrate(t.Context(), pool)
			if err != nil {
				t.Error(err)
			}
			mu.Lock()
			total += len(applied)
			mu.Unlock()
		})
	}
	wg.Wait()
	files, _ := migrations.ReadDir("migrations")
	if total != len(files) {
		t.Fatalf("migrations applied %d times in total, want %d", total, len(files))
	}
}

// Package postgres is a link.Store backed by PostgreSQL, using pgx.
package postgres

import (
	"context"
	"errors"
	"fmt"

	"github.com/Priyadharshan0903/gopath-academy/projects/shortener/internal/link"
	"github.com/jackc/pgx/v5"
	"github.com/jackc/pgx/v5/pgconn"
	"github.com/jackc/pgx/v5/pgxpool"
)

// Store implements link.Store.
type Store struct {
	pool *pgxpool.Pool
}

// NewStore returns a Store using pool. Run Migrate first.
func NewStore(pool *pgxpool.Pool) *Store { return &Store{pool: pool} }

// Create inserts l. The primary key on code makes the database reject
// duplicates atomically; that error becomes link.ErrCodeTaken.
func (s *Store) Create(ctx context.Context, l link.Link) error {
	_, err := s.pool.Exec(ctx,
		`INSERT INTO links (code, url, created_at) VALUES ($1, $2, $3)`,
		l.Code, l.URL, l.CreatedAt)
	var pgErr *pgconn.PgError
	if errors.As(err, &pgErr) && pgErr.Code == "23505" { // unique_violation
		return link.ErrCodeTaken
	}
	if err != nil {
		return fmt.Errorf("insert link: %w", err)
	}
	return nil
}

// Get returns the link for code, or link.ErrNotFound.
func (s *Store) Get(ctx context.Context, code string) (link.Link, error) {
	var l link.Link
	err := s.pool.QueryRow(ctx,
		`SELECT code, url, created_at FROM links WHERE code = $1`, code,
	).Scan(&l.Code, &l.URL, &l.CreatedAt)
	if errors.Is(err, pgx.ErrNoRows) {
		return link.Link{}, link.ErrNotFound
	}
	if err != nil {
		return link.Link{}, fmt.Errorf("select link: %w", err)
	}
	l.CreatedAt = l.CreatedAt.UTC() // pgx returns timestamptz in the local time zone
	return l, nil
}

// Delete removes the link for code, or returns link.ErrNotFound.
func (s *Store) Delete(ctx context.Context, code string) error {
	tag, err := s.pool.Exec(ctx, `DELETE FROM links WHERE code = $1`, code)
	if err != nil {
		return fmt.Errorf("delete link: %w", err)
	}
	if tag.RowsAffected() == 0 {
		return link.ErrNotFound
	}
	return nil
}

