package main

import (
	"io/fs"
	"net/http"
	"path"
	"strings"
)

// newHandler returns the HTTP handler for the site stored in site.
func newHandler(site fs.FS) http.Handler {
	mux := http.NewServeMux()
	mux.HandleFunc("GET /healthz", func(w http.ResponseWriter, _ *http.Request) {
		w.Header().Set("Content-Type", "text/plain; charset=utf-8")
		_, _ = w.Write([]byte("ok"))
	})
	mux.Handle("/", staticHandler(site))
	return mux
}

// staticHandler serves files from site and falls back to 404.html.
func staticHandler(site fs.FS) http.Handler {
	files := http.FileServerFS(site)
	return http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		if !exists(site, r.URL.Path) {
			serveNotFound(w, site)
			return
		}
		setCacheHeaders(w, r.URL.Path)
		files.ServeHTTP(w, r)
	})
}

// exists reports whether urlPath maps to a file, or to a directory
// containing index.html.
func exists(site fs.FS, urlPath string) bool {
	name := strings.TrimPrefix(path.Clean("/"+urlPath), "/")
	if name == "" {
		name = "."
	}
	fi, err := fs.Stat(site, name)
	if err != nil {
		return false
	}
	if fi.IsDir() {
		_, err = fs.Stat(site, path.Join(name, "index.html"))
		return err == nil
	}
	return true
}

func serveNotFound(w http.ResponseWriter, site fs.FS) {
	body, err := fs.ReadFile(site, "404.html")
	if err != nil {
		http.NotFound(w, nil)
		return
	}
	w.Header().Set("Content-Type", "text/html; charset=utf-8")
	w.WriteHeader(http.StatusNotFound)
	_, _ = w.Write(body)
}

// setCacheHeaders lets browsers cache fingerprinted assets for a long
// time while always revalidating HTML pages.
func setCacheHeaders(w http.ResponseWriter, urlPath string) {
	switch path.Ext(urlPath) {
	case ".css", ".js", ".woff2", ".png", ".svg", ".jpg", ".webp", ".ico":
		w.Header().Set("Cache-Control", "public, max-age=86400")
	default:
		w.Header().Set("Cache-Control", "no-cache")
	}
}

deploy/server/main.go.content:
// Command server serves the built website.
//
// It is intentionally small: a static file server with a health check,
// sensible timeouts, a custom 404 page and graceful shutdown. It is the
// workload we run on Kubernetes in the K8s track.
package main

import (
	"context"
	"errors"
	"flag"
	"log/slog"
	"net/http"
	"os"
	"os/signal"
	"syscall"
	"time"
)

func main() {
	addr := flag.String("addr", ":8080", "listen address")
	dir := flag.String("dir", "public", "directory with the built site")
	shutdownDelay := flag.Duration("shutdown-delay", 0, "keep serving this long after SIGTERM, while Kubernetes removes the pod from load balancing (lesson 15.2)")
	flag.Parse()

	logger := slog.New(slog.NewJSONHandler(os.Stdout, nil))

	if fi, err := os.Stat(*dir); err != nil || !fi.IsDir() {
		logger.Error("site directory not found", "dir", *dir)
		os.Exit(1)
	}

	srv := &http.Server{
		Addr:              *addr,
		Handler:           newHandler(os.DirFS(*dir)),
		ReadHeaderTimeout: 5 * time.Second,
		ReadTimeout:       10 * time.Second,
		WriteTimeout:      30 * time.Second,
		IdleTimeout:       120 * time.Second,
	}

	// Kubernetes sends SIGTERM before killing a pod. Stop accepting new
	// connections and let in-flight requests finish.
	ctx, stop := signal.NotifyContext(context.Background(), os.Interrupt, syscall.SIGTERM)
	defer stop()

	go func() {
		logger.Info("listening", "addr", *addr, "dir", *dir)
		if err := srv.ListenAndServe(); err != nil && !errors.Is(err, http.ErrServerClosed) {
			logger.Error("server failed", "err", err)
			os.Exit(1)
		}
	}()

	<-ctx.Done()
	logger.Info("shutting down", "delay", *shutdownDelay)
	time.Sleep(*shutdownDelay)
	shutdownCtx, cancel := context.WithTimeout(context.Background(), 15*time.Second)
	defer cancel()
	if err := srv.Shutdown(shutdownCtx); err != nil {
		logger.Error("graceful shutdown failed", "err", err)
		os.Exit(1)
	}
}
